INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(2, 'who-i-am', 'Who I am', '我是谁', 'https://traffic.libsyn.com/secure/learnchinese/1064.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/1064-r43trnj4fy2oih4hjg4k8nl7u9kcxomy6h5v9ve6s4.jpg', '', 'HSK1', 'https://mandarinbean.com/who-i-am/', '我的名字叫李大卫我是美国人但是在日本长大在英国上大学现在在中国工作我在大学学习历史和英语现在是一个英语老师我非常喜欢我的工作学生们很好学校也很好', 'wǒ de míng zì jiào Lǐ Dàwèi wǒ shì Měiguó rén dàn shì zài Rìběn zhǎng dà zài Yīngguó shàng dà xué xiàn zài zài Zhōngguó gōng zuò wǒ zài dà xué xué xí lì shǐ hé Yīngyǔ xiàn zài shì yī gè Yīngyǔ lǎo shī wǒ fēi cháng xǐ huān wǒ de gōng zuò xué shēng men hěn hǎo xué xiào yě hěn hǎo', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"wǒ de:&lt;br /&gt;\r\nmy, mine \"><ruby><span class=\"si\">我的</span><span class=\"tr\">我的</span><rt>wǒ de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"míng zì:&lt;br /&gt;\r\nname (HSK1)\"><ruby><span class=\"si\">名字</span><span class=\"tr\">名字</span><rt>míng zì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jiào:&lt;br /&gt;\r\ncalled (HSK1)\"><ruby><span class=\"si\">叫</span><span class=\"tr\">叫</span><rt>jiào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Lǐ Dàwèi:&lt;br /&gt;\r\nDavid Lee \"><ruby><span class=\"si\">李大卫</span><span class=\"tr\">李大衛</span><rt>Lǐ Dàwèi</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Měiguó:&lt;br /&gt;\r\nUS \"><ruby><span class=\"si\">美国</span><span class=\"tr\">美國</span><rt>Měiguó</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rén:&lt;br /&gt;\r\npeople, person (HSK1)\"><ruby><span class=\"si\">人</span><span class=\"tr\">人</span><rt>rén</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"dàn shì:&lt;br /&gt;\r\nbut (HSK2)\"><ruby><span class=\"si\">但是</span><span class=\"tr\">但是</span><rt>dàn shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zài:&lt;br /&gt;\r\n(located) at / (to be) in (HSK1)\"><ruby><span class=\"si\">在</span><span class=\"tr\">在</span><rt>zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Rìběn:&lt;br /&gt;\r\nJapan \"><ruby><span class=\"si\">日本</span><span class=\"tr\">日本</span><rt>Rìběn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhǎng dà:&lt;br /&gt;\r\ngrow up \"><ruby><span class=\"si\">长大</span><span class=\"tr\">長大</span><rt>zhǎng dà</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"zài:&lt;br /&gt;\r\n(located) at / (to be) in (HSK1)\"><ruby><span class=\"si\">在</span><span class=\"tr\">在</span><rt>zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Yīngguó:&lt;br /&gt;\r\nU.K. \"><ruby><span class=\"si\">英国</span><span class=\"tr\">英國</span><rt>Yīngguó</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shàng:&lt;br /&gt;\r\ntake, go to (HSK1)\"><ruby><span class=\"si\">上</span><span class=\"tr\">上</span><rt>shàng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dà xué:&lt;br /&gt;\r\nUniversity \"><ruby><span class=\"si\">大学</span><span class=\"tr\">大學</span><rt>dà xué</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"xiàn zài:&lt;br /&gt;\r\nnow (HSK1)\"><ruby><span class=\"si\">现在</span><span class=\"tr\">現在</span><rt>xiàn zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zài:&lt;br /&gt;\r\n(located) at / (to be) in (HSK1)\"><ruby><span class=\"si\">在</span><span class=\"tr\">在</span><rt>zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Zhōngguó:&lt;br /&gt;\r\nChina (HSK1)\"><ruby><span class=\"si\">中国</span><span class=\"tr\">中國</span><rt>Zhōngguó</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gōng zuò:&lt;br /&gt;\r\nWork (HSK1)\"><ruby><span class=\"si\">工作</span><span class=\"tr\">工作</span><rt>gōng zuò</rt></ruby></abbr>。 <abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zài:&lt;br /&gt;\r\n(located) at / (to be) in (HSK1)\"><ruby><span class=\"si\">在</span><span class=\"tr\">在</span><rt>zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dà xué:&lt;br /&gt;\r\nUniversity \"><ruby><span class=\"si\">大学</span><span class=\"tr\">大學</span><rt>dà xué</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xué xí:&lt;br /&gt;\r\nstudy (HSK1)\"><ruby><span class=\"si\">学习</span><span class=\"tr\">學習</span><rt>xué xí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"lì shǐ:&lt;br /&gt;\r\nhistory (HSK3)\"><ruby><span class=\"si\">历史</span><span class=\"tr\">歷史</span><rt>lì shǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hé:&lt;br /&gt;\r\nand, with (HSK1)\"><ruby><span class=\"si\">和</span><span class=\"tr\">和</span><rt>hé</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Yīngyǔ:&lt;br /&gt;\r\nEnglish \"><ruby><span class=\"si\">英语</span><span class=\"tr\">英語</span><rt>Yīngyǔ</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"xiàn zài:&lt;br /&gt;\r\nnow (HSK1)\"><ruby><span class=\"si\">现在</span><span class=\"tr\">現在</span><rt>xiàn zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī:&lt;br /&gt;\r\none (HSK1)\"><ruby><span class=\"si\">一</span><span class=\"tr\">一</span><rt>yī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gè:&lt;br /&gt;\r\n(measure word) (HSK1)\"><ruby><span class=\"si\">个</span><span class=\"tr\">個</span><rt>gè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Yīngyǔ:&lt;br /&gt;\r\nEnglish \"><ruby><span class=\"si\">英语</span><span class=\"tr\">英語</span><rt>Yīngyǔ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"lǎo shī:&lt;br /&gt;\r\nteacher (HSK1)\"><ruby><span class=\"si\">老师</span><span class=\"tr\">老師</span><rt>lǎo shī</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"fēi cháng:&lt;br /&gt;\r\nvery (HSK2)\"><ruby><span class=\"si\">非常</span><span class=\"tr\">非常</span><rt>fēi cháng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xǐ huān:&lt;br /&gt;\r\nlike (HSK1)\"><ruby><span class=\"si\">喜欢</span><span class=\"tr\">喜歡</span><rt>xǐ huān</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǒ de:&lt;br /&gt;\r\nmy, mine \"><ruby><span class=\"si\">我的</span><span class=\"tr\">我的</span><rt>wǒ de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gōng zuò:&lt;br /&gt;\r\nWork (HSK1)\"><ruby><span class=\"si\">工作</span><span class=\"tr\">工作</span><rt>gōng zuò</rt></ruby></abbr>。 <abbr rel=\"tooltip\" title=\"xué shēng:&lt;br /&gt;\r\nstudent (HSK1)\"><ruby><span class=\"si\">学生</span><span class=\"tr\">學生</span><rt>xué shēng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"men:&lt;br /&gt;\r\n(aux. plural) \"><ruby><span class=\"si\">们</span><span class=\"tr\">們</span><rt>men</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn:&lt;br /&gt;\r\nvery (HSK1)\"><ruby><span class=\"si\">很</span><span class=\"tr\">很</span><rt>hěn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hǎo:&lt;br /&gt;\r\ngood, well (HSK1)\"><ruby><span class=\"si\">好</span><span class=\"tr\">好</span><rt>hǎo</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"xué xiào:&lt;br /&gt;\r\nschool (HSK1)\"><ruby><span class=\"si\">学校</span><span class=\"tr\">學校</span><rt>xué xiào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yě:&lt;br /&gt;\r\nalso (HSK2)\"><ruby><span class=\"si\">也</span><span class=\"tr\">也</span><rt>yě</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn:&lt;br /&gt;\r\nvery (HSK1)\"><ruby><span class=\"si\">很</span><span class=\"tr\">很</span><rt>hěn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hǎo:&lt;br /&gt;\r\ngood, well (HSK1)\"><ruby><span class=\"si\">好</span><span class=\"tr\">好</span><rt>hǎo</rt></ruby></abbr>。</p>\r\n</div>\r\n</div>', '2025-11-15 02:48:53'),
(3, 'do-you-know-them', 'Do you know them?', '你认识他们吗？', 'https://traffic.libsyn.com/secure/learnchinese/1063.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/1063-qkev1l0noxekbjmvqa5u470d2mvonal939no7w3ryq.jpg', '', 'HSK1', 'https://mandarinbean.com/do-you-know-them/', '你认识这两个人吗她是我的中文老师姓王他是我弟弟的英文老师姓李王老师很漂亮她今年二十八岁喜欢旅游和跑步李老师很高今年三十二岁在大学工作他们两个人认识五年了有一个女儿和一个儿子女儿一岁儿子三岁他们会说中文也会说英文王老师和李老师都是很好的人我和弟弟都很喜欢他们', 'nǐ rèn shí zhè liǎng gè rén ma tā shì wǒ de zhōng wén lǎo shī xìng Wáng tā shì wǒ dì dì de yīng wén lǎo shī xìng Lǐ Wáng lǎo shī hěn piào liàng tā jīn nián èr shí bā suì xǐ huān lǚ yóu hé pǎo bù Lǐ lǎo shī hěn gāo jīn nián sān shí èr suì zài dà xué gōng zuò tā men liǎng gè rén rèn shí wǔ nián le yǒu yī gè nǚ ér hé yī gè ér zi nǚ ér yī suì ér zi sān suì tā men huì shuō zhōng wén yě huì shuō yīng wén Wáng lǎo shī hé Lǐ lǎo shī dōu shì hěn hǎo de rén wǒ hé dì dì dōu hěn xǐ huān tā men', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rèn shí:&lt;br /&gt;\r\nknow (HSK1)\"><ruby><span class=\"si\">认识</span><span class=\"tr\">認識</span><rt>rèn shí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhè:&lt;br /&gt;\r\nthis (HSK1)\"><ruby><span class=\"si\">这</span><span class=\"tr\">這</span><rt>zhè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"liǎng:&lt;br /&gt;\r\ntwo (HSK2)\"><ruby><span class=\"si\">两</span><span class=\"tr\">兩</span><rt>liǎng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gè:&lt;br /&gt;\r\n(measure word) (HSK1)\"><ruby><span class=\"si\">个</span><span class=\"tr\">個</span><rt>gè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rén:&lt;br /&gt;\r\npeople, person (HSK1)\"><ruby><span class=\"si\">人</span><span class=\"tr\">人</span><rt>rén</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ma:&lt;br /&gt;\r\n(aux. question mark) (HSK1)\"><ruby><span class=\"si\">吗</span><span class=\"tr\">嗎</span><rt>ma</rt></ruby></abbr>？<abbr rel=\"tooltip\" title=\"tā:&lt;br /&gt;\r\nshe, her (HSK1)\"><ruby><span class=\"si\">她</span><span class=\"tr\">她</span><rt>tā</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǒ de:&lt;br /&gt;\r\nmy, mine\"><ruby><span class=\"si\">我的</span><span class=\"tr\">我的</span><rt>wǒ de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhōng wén:&lt;br /&gt;\r\nChinese (HSK4)\"><ruby><span class=\"si\">中文</span><span class=\"tr\">中文</span><rt>zhōng wén</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"lǎo shī:&lt;br /&gt;\r\nteacher (HSK1)\"><ruby><span class=\"si\">老师</span><span class=\"tr\">老師</span><rt>lǎo shī</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"xìng:&lt;br /&gt;\r\nsurname (HSK2)\"><ruby><span class=\"si\">姓</span><span class=\"tr\">姓</span><rt>xìng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Wáng:&lt;br /&gt;\r\nWang\"><ruby><span class=\"si\">王</span><span class=\"tr\">王</span><rt>Wáng</rt></ruby></abbr>；<abbr rel=\"tooltip\" title=\"tā:&lt;br /&gt;\r\nhe, him (HSK1)\"><ruby><span class=\"si\">他</span><span class=\"tr\">他</span><rt>tā</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dì dì:&lt;br /&gt;\r\nyounger brother (HSK2)\"><ruby><span class=\"si\">弟弟</span><span class=\"tr\">弟弟</span><rt>dì dì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"d