INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(15, 'wash-the-face', 'Wash the Face', '洗脸', 'https://traffic.libsyn.com/learnchinese/Wash_the_Face-1053.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/1053-o2z395uj5lcnrlxcjgvhbehqgdbe85vwnz6thigw4s.jpg', '', 'HSK1', 'https://mandarinbean.com/wash-the-face/', '岁的小波不喜欢洗脸有一天老师看见他的脸很脏就说你怎么每天不洗脸吃的早饭渣还在脸上呢小波说老师那你猜猜我吃的是什么老师说米饭小波说老师你猜错了那是昨天吃的', 'suì de xiǎo bō bù xǐ huān xǐ liǎn yǒu yī tiān lǎo shī kàn jiàn tā de liǎn hěn zāng jiù shuō nǐ zěn me měi tiān bù xǐ liǎn chī de zǎo fàn zhā hái zài liǎn shàng ne xiǎo bō shuō lǎo shī nà nǐ cāi cāi wǒ chī de shì shén me lǎo shī shuō mǐ fàn xiǎo bō shuō lǎo shī nǐ cāi cuò le nà shì zuó tiān chī de', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p>7<abbr rel=\"tooltip\" title=\"suì :&lt;br /&gt;\r\nyear old (HSK1)\"><ruby><span class=\"si\">岁</span><span class=\"tr\">歲</span><rt>suì </rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de :&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de </rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎo bō :&lt;br /&gt;\r\nXiaobo\"><ruby><span class=\"si\">小波</span><span class=\"tr\">小波</span><rt>xiǎo bō </rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bù :&lt;br /&gt;\r\nno, not (HSK1)\"><ruby><span class=\"si\">不</span><span class=\"tr\">不</span><rt>bù </rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xǐ huān :&lt;br /&gt;\r\nlike (HSK1)\"><ruby><span class=\"si\">喜欢</span><span class=\"tr\">喜歡</span><rt>xǐ huān </rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xǐ :&lt;br /&gt;\r\nwash (HSK2)\"><ruby><span class=\"si\">洗</span><span class=\"tr\">洗</span><rt>xǐ </rt></ruby></abbr><abbr rel=\"tooltip\" title=\"liǎn :&lt;br /&gt;\r\nface (HSK3)\"><ruby><span class=\"si\">脸</span><span class=\"tr\">臉</span><rt>liǎn <