INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(33, 'this-is-my-boyfriend', 'This is my boyfriend', '这是我的男朋友', 'https://traffic.libsyn.com/secure/learnchinese/2127.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/2127-qvo9vspufbuq7g6aqyt2f8xe5t3huflki6cby17nma.jpg', '', 'HSK2', 'https://mandarinbean.com/this-is-my-boyfriend/', '我有男朋友了他的名字叫张阳他不胖也不瘦个子很高喜欢运动我们认识三年半了张阳是我哥哥的同学但是哥哥对他不满意因为他没有工作张阳有一个妹妹还是个中学生我很喜欢这个女孩非常聪明可爱张阳的妈妈是护士他的爸爸在一个小公司工作我还没见过他们这就是我的男朋友和他的家人你觉得怎么样', 'wǒ yǒu nán péng yǒu le tā de míng zì jiào Zhāng Yáng tā bù pàng yě bù shòu gè zi hěn gāo xǐ huān yùn dòng wǒ men rènshi sān nián bàn le Zhāng Yáng shì wǒ gēge de tóng xué dàn shì gēge duì tā bù mǎn yì yīn wèi tā méi yǒu gōng zuò Zhāng Yáng yǒu yī gè mèimei hái shì gè zhōng xué shēng wǒ hěn xǐ huān zhè gè nǚ hái fēi cháng cōng míng kě ài Zhāng Yáng de māma shì hù shì tā de bàba zài yī gè xiǎo gōng sī gōng zuò wǒ hái méi jiàn guò tā men zhè jiù shì wǒ de nán péng yǒu hé tā de jiā rén nǐ jué de zěn me yàng', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yǒu:&lt;br /&gt;\r\nhave, there be (HSK1)\"><ruby><span class=\"si\">有</span><span class=\"tr\">有</span><rt>yǒu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nán péng yǒu:&lt;br /&gt;\r\nBoy friend \"><ruby><span class=\"si\">男朋友</span><span class=\"tr\">男朋友</span><rt>nán péng yǒu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"tā de:&lt;br /&gt;\r\nhis \"><ruby><span class=\"si\">他的</span><span class=\"tr\">他的</span><rt>tā de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"míng zì:&lt;br /&gt;\r\nname (HSK1)\"><ruby><span class=\"si\">名字</span><span class=\"tr\">名字</span><rt>míng zì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jiào:&lt;br /&gt;\r\nCall (HSK1)\"><ruby><span class=\"si\">叫</span><span class=\"tr\">叫</span><rt>jiào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Zhāng Yáng:&lt;br /&gt;\r\nZhang Yang \"><ruby><span class=\"si\">张阳</span><span class=\"tr\">張陽</span><rt>Zhāng Yáng</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"tā:&lt;br /&gt;\r\nhe, him (HSK1)\"><ruby><span class=\"si\">他</span><span class=\"tr\">他</span><rt>tā</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bù:&lt;br /&gt;\r\nno, not (HSK1)\"><ruby><span class=\"si\">不</span><span class=\"tr\">不</span><rt>bù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"pàng:&lt;br /&gt;\r\nfat (HSK3)\"><ruby><span class=\"si\">胖</span><span class=\"tr\">胖</span><rt>pàng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yě:&lt;br /&gt;\r\nalso (HSK2)\"><ruby><span class=\"si\">也</span><span class=\"tr\">也</span><rt>yě</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bù:&lt;br /&gt;\r\nno, not (HSK1)\"><ruby><span class=\"si\">不</span><span class=\"tr\">不</span><rt>bù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shòu:&lt;br /&gt;\r\nthin (HSK3)\"><ruby><span class=\"si\">瘦</span><span class=\"tr\">瘦</span><rt>shòu</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"gè zi:&lt;br /&gt;\r\nheight (HSK4)\"><ruby><span class=\"si\">个子</span><span class=\"tr\">個子</span><rt>gè zi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn:&lt;br /&gt;\r\nvery (HSK1)\"><ruby><span class=\"si\">很</span><span class=\"tr\">很</span><rt>hěn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gāo:&lt;br /&gt;\r\nhigh (HSK2)\"><ruby><span class=\"si\">高</span><span class=\"tr\">高</span><rt>gāo</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"xǐ huān:&lt;br /&gt;\r\nlike (HSK1)\"><ruby><span class=\"si\">喜欢</span><span class=\"tr\">喜歡</span><rt>xǐ huān</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yùn dòng:&lt;br /&gt;\r\nsports, movement (HSK2)\"><ruby><span class=\"si\">运动</span><span class=\"tr\">運動</span><rt>yùn dòng</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"wǒ men:&lt;br /&gt;\r\nwe, us (HSK1)\"><ruby><span class=\"si\">我们</span><span class=\"tr\">我們</span><rt>wǒ men</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rènshi:&lt;br /&gt;\r\nknow (HSK1)\"><ruby><span class=\"si\">认识</span><span class=\"tr\">認識</span><rt>rènshi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"sān:&lt;br /&gt;\r\nthree (HSK1)\"><ruby><span class=\"si\">三</span><span class=\"tr\">三</span><rt>sān</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nián:&lt;br /&gt;\r\nYear (HSK1)\"><ruby><span class=\"si\">年</span><span class=\"tr\">年</span><rt>nián</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bàn:&lt;br /&gt;\r\nHalf (HSK3)\"><ruby><span class=\"si\">半</span><span class=\"tr\">半</span><rt>bàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"Zhāng Yáng:&lt;br /&gt;\r\nZhang Yang \"><ruby><span class=\"si\">张阳</span><span class=\"tr\">張陽</span><rt>Zhāng Yáng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gēge:&lt;br /&gt;\r\nelder brother (HSK2)\"><ruby><span class=\"si\">哥哥</span><span class=\"tr\">哥哥</span><rt>gēge</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"tóng xué:&lt;br /&gt;\r\nclassmate (HSK1)\"><ruby><span class=\"si\">同学</span><span class=\"tr\">同學</span><rt>tóng xué</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"dàn shì:&lt;br /&gt;\r\nbut (HSK2)\"><ruby><span class=\"si\">但是</span><span class=\"tr\">但是</span><rt>dàn shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gēge:&lt;br /&gt;\r\nelder brother (HSK2)\"><ruby><span class=\"si\">哥哥</span><span class=\"tr\">哥哥</span><rt>gēge</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"duì:&lt;br /&gt;\r\nto, for (HSK2)\"><ruby><span class=\"si\">对</span><span class=\"tr\">對</span><rt>duì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"tā:&lt;br /&gt;\r\nhe, him (HSK1)\"><ruby><span class=\"si\">他</span><span class=\"tr\">他</span><rt>tā</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bù:&lt;br /&gt;\r\nno, not (HSK1)\"><ruby><span class=\"si\">不</span><span class=\"tr\">不</span><rt>bù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"mǎn yì:&lt;br /&gt;\r\nsatisfy (HSK3)\"><ruby><span class=\"si\">满意</span><span class=\"tr\">滿意</span><rt>mǎn yì</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"yīn wèi:&lt;br /&gt;\r\nbecause (HSK2)\"><ruby><span class=\"si\">因为</span><span class=\"tr\">因爲</span><rt>yīn wèi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"tā:&lt;br /&gt;\r\nhe, him (HSK1)\"><ruby><span class=\"si\">他</span><span class=\"tr\">他</span><rt>tā</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"méi yǒu:&lt;br /&gt;\r\nNo \"><ruby><span class=\"si\">没有</span><span class=\"tr\">沒有</span><rt>méi yǒu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gōng zuò:&lt;br /&gt;\r\nWork (HSK1)\"><ruby><span class=\"si\">工作</span><span class=\"tr\">工作</span><rt>gōng zuò</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"Zhāng Yáng:&lt;br /&gt;\r\nZhang Yang \"><ruby><span class=\"si\">张阳</span><span class=\"tr\">張陽</span><rt>Zhāng Yáng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yǒu:&lt;br /&gt;\r\nhave, there be (HSK1)\"><ruby><span class=\"si\">有</span><span class=\"tr\">有</span><rt>yǒu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī:&lt;br /&gt;\r\none (HSK1)\"><ruby><span class=\"si\">一</span><span class=\"tr\">一</span><rt>yī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gè:&lt;br /&gt;\r\n(measure word) (HSK1)\"><ruby><span class=\"si\">个</span><span class=\"tr\">個</span><rt>gè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"mèimei:&lt;br /&gt;\r\nyounger sister (HSK2)\"><ruby><span class=\"si\">妹妹</span><span class=\"tr\">妹妹</span><rt>mèimei</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"hái:&lt;br /&gt;\r\nstill (HSK2)\"><ruby><span class=\"si\">还</span><span class=\"tr\">還</span><rt>hái</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gè:&lt;br /&gt;\r\n(measure word) (HSK1)\"><ruby><span class=\"si\">个</span><span class=\"tr\">個</span><rt>gè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhōng xué shēng:&lt;br /&gt;\r\nmiddle school student \"><ruby><span class=\"si\">中学生</span><span class=\"tr\">中學生</span><rt>zhōng xué shēng</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn:&lt;br /&gt;\r\nvery (HSK1)\"><ruby><span class=\"si\">很</span><span class=\"tr\">很</span><rt>hěn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xǐ huān:&lt;br /&gt;\r\nlike (HSK1)\"><ruby><span class=\"si\">喜欢</span><span class=\"tr\">喜歡</span><rt>xǐ huān</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhè:&lt;br /&gt;\r\nthis (HSK1)\"><ruby><span class=\"si\">这</span><span class=\"tr\">這</span><rt>zhè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gè:&lt;br /&gt;\r\n(measure word) (HSK1)\"><ruby><span class=\"si\">个</span><span class=\"tr\">個</span><rt>gè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǚ hái:&lt;br /&gt;\r\ngirl \"><ruby><span class=\"si\">女孩</span><span class=\"tr\">女孩</span><rt>nǚ hái</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"fēi cháng:&lt;br /&gt;\r\nvery (HSK2)\"><ruby><span class=\"si\">非常</span><span class=\"tr\">非常</span><rt>fēi cháng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"cōng míng:&lt;br /&gt;\r\nclever (HSK3)\"><ruby><span class=\"si\">聪明</span><span class=\"tr\">聰明</span><rt>cōng míng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"kě ài:&lt;br /&gt;\r\ncute (HSK3)\"><ruby><span class=\"si\">可爱</span><span class=\"tr\">可愛</span><rt>kě ài</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"Zhāng Yáng:&lt;br /&gt;\r\nZhang Yang \"><ruby><span class=\"si\">张阳</span><span class=\"tr\">張陽</span><rt>Zhāng Yáng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"māma:&lt;br /&gt;\r\nMother (HSK1)\"><ruby><span class=\"si\">妈妈</span><span class=\"tr\">媽媽</span><rt>māma</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hù shì:&lt;br /&gt;\r\nNurse (HSK4)\"><ruby><span class=\"si\">护士</span><span class=\"tr\">護士</span><rt>hù shì</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"tā de:&lt;br /&gt;\r\nhis \"><ruby><span class=\"si\">他的</span><span class=\"tr\">他的</span><rt>tā de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bàba:&lt;br /&gt;\r\ndad (HSK1)\"><ruby><span class=\"si\">爸爸</span><span class=\"tr\">爸爸</span><rt>bàba</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zài:&lt;br /&gt;\r\n(located) at / (to be) in (HSK1)\"><ruby><span class=\"si\">在</span><span class=\"tr\">在</span><rt>zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī:&lt;br /&gt;\r\none (HSK1)\"><ruby><span class=\"si\">一</span><span class=\"tr\">一</span><rt>yī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gè:&lt;br /&gt;\r\n(measure word) (HSK1)\"><ruby><span class=\"si\">个</span><span class=\"tr\">個</span><rt>gè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎo:&lt;br /&gt;\r\nSmall (HSK1)\"><ruby><span class=\"si\">小</span><span class=\"tr\">小</span><rt>xiǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gōng sī:&lt;br /&gt;\r\ncompany (HSK3)\"><ruby><span class=\"si\">公司</span><span class=\"tr\">公司</span><rt>gōng sī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gōng zuò:&lt;br /&gt;\r\nWork (HSK1)\"><ruby><span class=\"si\">工作</span><span class=\"tr\">工作</span><rt>gōng zuò</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hái:&lt;br /&gt;\r\nstill (HSK2)\"><ruby><span class=\"si\">还</span><span class=\"tr\">還</span><rt>hái</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"méi:&lt;br /&gt;\r\nno, not (HSK1)\"><ruby><span class=\"si\">没</span><span class=\"tr\">沒</span><rt>méi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jiàn:&lt;br /&gt;\r\nSee \"><ruby><span class=\"si\">见</span><span class=\"tr\">見</span><rt>jiàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"guò:&lt;br /&gt;\r\n(the structural particle, used after a verb indicating a past experience action which hasn\'t lasted to the present ) (HSK2)\"><ruby><span class=\"si\">过</span><span class=\"tr\">過</span><rt>guò</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"tā men:&lt;br /&gt;\r\nthey, them (HSK1)\"><ruby><span class=\"si\">他们</span><span class=\"tr\">他們</span><rt>tā men</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"zhè:&lt;br /&gt;\r\nthis (HSK1)\"><ruby><span class=\"si\">这</span><span class=\"tr\">這</span><rt>zhè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jiù:&lt;br /&gt;\r\njust, with regard to (HSK2)\"><ruby><span class=\"si\">就</span><span class=\"tr\">就</span><rt>jiù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǒ de:&lt;br /&gt;\r\nmy, mine \"><ruby><span class=\"si\">我的</span><span class=\"tr\">我的</span><rt>wǒ de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nán péng yǒu:&lt;br /&gt;\r\nBoy friend \"><ruby><span class=\"si\">男朋友</span><span class=\"tr\">男朋友</span><rt>nán péng yǒu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hé:&lt;br /&gt;\r\nand, with (HSK1)\"><ruby><span class=\"si\">和</span><span class=\"tr\">和</span><rt>hé</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"tā de:&lt;br /&gt;\r\nhis \"><ruby><span class=\"si\">他的</span><span class=\"tr\">他的</span><rt>tā de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jiā rén:&lt;br /&gt;\r\nfamily \"><ruby><span class=\"si\">家人</span><span class=\"tr\">家人</span><rt>jiā rén</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jué de:&lt;br /&gt;\r\nto think, to feel (HSK2)\"><ruby><span class=\"si\">觉得</span><span class=\"tr\">覺得</span><rt>jué de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zěn me yàng:&lt;br /&gt;\r\nHow about it (HSK1)\"><ruby><span class=\"si\">怎么样</span><span class=\"tr\">怎麽樣</span><rt>zěn me yàng</rt></ruby></abbr>？</p>\r\n</div>\r\n</div>', '2025-11-15 02:48:53'),
(34, 'citizen-of-the-world', 'Citizen of the World', '世界公民', 'https://traffic.libsyn.com/secure/learnchinese/2126.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/2126-qqb77guskplyygz334gfrhhso0ytycct6qfdvbbj2q.jpg', '', 'HSK2', 'https://mandarinbean.com/citizen-of-the-world/', '我是哪里人这个问题很难回答我的爸爸是美国人妈妈是韩国人我在泰国出生在中国长大现在在法国读大学我爱每个地方的文化也会说不同国家的语言还有很多不同国家的朋友你问我是哪里人我会说我是世界公民你呢你是哪里人', 'wǒ shì nǎ lǐ rén zhè gè wèn tí hěn nán huí dá wǒ de bàba shì Měiguó rén māma shì Hánguó rén wǒ zài Tàiguó chū shēng zài Zhōngguó zhǎng dà xiàn zài zài Fǎguó dú dà xué wǒ ài měi gè dì fāng de wén huà yě huì shuō bù tóng guó jiā de yǔ yán hái yǒu hěn duō bù tóng guó jiā de péng yǒu nǐ wèn wǒ shì nǎ lǐ rén wǒ huì shuō wǒ shì shì jiè gōng mín nǐ ne nǐ shì nǎ lǐ rén', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǎ lǐ:&lt;br /&gt;\r\nwhere \"><ruby><span class=\"si\">哪里</span><span class=\"tr\">哪裏</span><rt>nǎ lǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rén:&lt;br /&gt;\r\npeople, person (HSK1)\"><ruby><span class=\"si\">人</span><span class=\"tr\">人</span><rt>rén</rt></ruby></abbr>？<abbr rel=\"tooltip\" title=\"zhè:&lt;br /&gt;\r\nthis (HSK1)\"><ruby><span class=\"si\">这</span><span class=\"tr\">這</span><rt>zhè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gè:&lt;br /&gt;\r\n(measure word) (HSK1)\"><ruby><span class=\"si\">个</span><span class=\"tr\">個</span><rt>gè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wèn tí:&lt;br /&gt;\