INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(40, 'what-country-are-you-from', 'What country are you from?', '你是哪国人？', 'https://traffic.libsyn.com/secure/learnchinese/2120.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/2120-qfvghga2ctbkj6h08m2tm5k7y4rf0hwnsj9oa8r70y.jpg', '', 'HSK2', 'https://mandarinbean.com/what-country-are-you-from/', '大龙你好我叫大龙请问你是留学生吗铃美是我是留学生我叫铃美大龙你是哪国人铃美我是日本人你呢大龙我来自美国我的中文名字叫大龙你也是日本人吗苏南哦不不我不是日本人我是泰国人我的名字叫苏南吴小咪大家好我叫吴小咪大龙你好你是日本人泰国人还是韩国人吴小咪哈哈我不是留学生我是中国人铃美你好我叫铃美来自日本他是大龙美国人苏南你好我叫苏南我是泰国人很高兴认识你吴小咪认识你们我也很高兴', 'Dàlóng nǐ hǎo wǒ jiào Dàlóng qǐng wèn nǐ shì liú xué shēng ma Língměi shì wǒ shì liú xué shēng wǒ jiào Língměi Dàlóng nǐ shì nǎ guó rén Língměi wǒ shì Rìběn rén nǐ ne Dàlóng wǒ lái zì měi guó wǒ de zhōng wén míng zì jiào Dàlóng nǐ yě shì Rìběn rén ma Sūnán ò bù bù wǒ bù shì Rìběn rén wǒ shì Tàiguó rén wǒ de míng zì jiào Sūnán Wú Xiǎomī dà jiā hǎo wǒ jiào Wú Xiǎomī Dàlóng nǐ hǎo nǐ shì Rìběn rén Tàiguó rén hái shì Hánguó rén Wú Xiǎomī hā hā wǒ bù shì liú xué shēng wǒ shì Zhōngguó rén Língměi nǐ hǎo wǒ jiào Língměi lái zì Rìběn tā shì Dàlóng měi guó rén Sūnán nǐ hǎo wǒ jiào Sūnán wǒ shì Tàiguó rén hěn gāo xìng rèn shí nǐ Wú Xiǎomī rèn shí nǐ men wǒ yě hěn gāo xìng', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"Dàlóng:&lt;br /&gt;\r\nDalong\"><ruby><span class=\"si\">大龙</span><span class=\"tr\">大龍</span><rt>Dàlóng</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"nǐ hǎo:&lt;br /&gt;\r\nHello\"><ruby><span class=\"si\">你好</span><span class=\"tr\">你好</span><rt>nǐ hǎo</rt></ruby></abbr>！<abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jiào:&lt;br /&gt;\r\nCall (HSK1)\"><ruby><span class=\"si\">叫</span><sp