INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(56, 'my-day', 'My day', '我的一天', 'https://traffic.libsyn.com/secure/learnchinese/3173.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/3173-r8jht9eogx3v7wbnywqi3otne3v98mu3oxwaimsvgy.jpg', '', 'HSK3', 'https://mandarinbean.com/my-day/', '明天要去深圳出差我计划今晚就准备好出差的东西明天早上七点一刻起床洗漱完就出发坐地铁太浪费时间了所以我准备打车去机场车上还能再睡四十五分钟到了机场差不多八点半可以吃个早餐然后准备登机上飞机以后买个空中然后准时参加公司九点的线上会议下飞机以后等同事来接我然后去酒店放行李中午约朋友吃午饭下午两点差十分准时到达公司的深圳办公室开始下午的工作大概工作四个小时左右我就可以回酒店休息了这就是我一天的计划', 'míng tiān yào qù Shēnzhèn chū chāi wǒ jì huà jīn wǎn jiù zhǔn bèi hǎo chū chāi de dōng xi míng tiān zǎo shàng qī diǎn yī kè qǐ chuáng xǐ shù wán jiù chū fā zuò dì tiě tài làng fèi shí jiān le suǒ yǐ wǒ zhǔn bèi dǎ chē qù jī chǎng chē shàng hái néng zài shuì sì shí wǔ fēn zhōng dào le jī chǎng chà bù duō bā diǎn bàn kě yǐ chī gè zǎo cān rán hòu zhǔn bèi dēng jī shàng fēi jī yǐ hòu mǎi gè kōng zhōng rán hòu zhǔn shí cān jiā gōng sī jiǔ diǎn de xiàn shàng huì yì xià fēi jī yǐ hòu děng tóng shì lái jiē wǒ rán hòu qù jiǔ diàn fàng xíng lǐ zhōng wǔ yuē péng yǒu chī wǔ fàn xià wǔ liǎng diǎn chà shí fēn zhǔn shí dào dá gōng sī de shēn zhèn bàn gōng shì kāi shǐ xià wǔ de gōng zuò dà gài gōng zuò sì gè xiǎo shí zuǒ yòu wǒ jiù kě yǐ huí jiǔ diàn xiū xi le zhè jiù shì wǒ yī tiān de jì huà', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"míng tiān:&lt;br /&gt;\r\ntomorrow (HSK1)\"><ruby><span class=\"si\">明天</span><span class=\"tr\">明天</span><rt>míng tiān</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yào:&lt;br /&gt;\r\nto want to, would like to (HSK2)\"><ruby><span class=\"si\">要</span><span class=\"tr\">要</span><rt>yào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Shēnzhèn:&lt;br /&gt;\r\nShenzhen \"><ruby><span class=\"si\">深圳</span><span class=\"tr\">深圳</span><rt>Shēnzhèn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"chū chāi:&lt;br /&gt;\r\non business trip (HSK4)\"><ruby><span class=\"si\">出差</span><span class=\"tr\">出差</span><rt>chū chāi</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jì huà:&lt;br /&gt;\r\nplan (HSK4)\"><ruby><span class=\"si\">计划</span><span class=\"tr\">計劃</span><rt>jì huà</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jīn wǎn:&lt;br /&gt;\r\ntonight \"><ruby><span class=\"si\">今晚</span><span class=\"tr\">今晚</span><rt>jīn wǎn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jiù:&lt;br /&gt;\r\njust, with regard to (HSK2)\"><ruby><span class=\"si\">就</span><span class=\"tr\">就</span><rt>jiù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhǔn bèi:&lt;br /&gt;\r\nprepare (HSK2)\"><ruby><span class=\"si\">准备</span><span class=\"tr\">準備</span><rt>zhǔn bèi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hǎo:&lt;br /&gt;\r\ngood, well (HSK1)\"><ruby><span class=\"si\">好</span><span class=\"tr\">好</span><rt>hǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"chū chāi:&lt;br /&gt;\r\non business trip (HSK4)\"><ruby><span class=\"si\">出差</span><span class=\"tr\">出差</span><rt>chū chāi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dōng xi:&lt;br /&gt;\r\nthing, stuff (HSK1)\"><ruby><span class=\"si\">东西</span><span class=\"tr\">東西</span><rt>dōng xi</rt></ruby></abbr>。 <abbr rel=\"tooltip\" title=\"míng tiān:&lt;br /&gt;\r\ntomorrow (HSK1)\"><ruby><span class=\"si\">明天</span><span class=\"tr\">明天</span><rt>míng tiān</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zǎo shàng:&lt;br