INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(58, 'age-story', 'Age', '年纪', 'https://traffic.libsyn.com/secure/learnchinese/3171.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/3171-r73qgrljn4ytiuhgxzvee7vgvz36g3x6zbhprrpxi6.png', '', 'HSK3', 'https://mandarinbean.com/age-story/', '商店的服务员阿姨觉得妈妈看起来很年轻爸爸也很高兴他们开始猜阿姨多大年纪阿姨说你们猜猜我多少岁妈妈想了想说我觉得你四十岁左右阿姨笑了说不对我今年五十岁了大家都感到惊讶然后他们又聊起了属相哪年出生的问题也变得有趣起来', 'shāng diàn de fú wù yuán ā yí jué de māma kàn qǐ lái hěn nián qīng bàba yě hěn gāo xìng tā men kāi shǐ cāi ā yí duō dà nián jì ā yí shuō nǐ men cāi cāi wǒ duō shǎo suì māma xiǎng le xiǎng shuō wǒ jué de nǐ sì shí suì zuǒ yòu ā yí xiào le shuō bù duì wǒ jīn nián wǔ shí suì le dà jiā dōu gǎn dào jīng yà rán hòu tā men yòu liáo qǐ le shǔ xiàng nǎ nián chū shēng de wèn tí yě biàn de yǒu qù qǐ lái', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"shāng diàn:&lt;br /&gt;\r\nshop (HSK1)\"><ruby><span class=\"si\">商店</span><span class=\"tr\">商店</span><rt>shāng diàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"fú wù yuán:&lt;br /&gt;\r\nattendant (HSK2)\"><ruby><span class=\"si\">服务员</span><span class=\"tr\">服務員</span><rt>fú wù yuán</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ā yí:&lt;br /&gt;\r\nAunt (HSK3)\"><ruby><span class=\"si\">阿姨</span><span class=\"tr\">阿姨</span><rt>ā yí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jué de:&lt;br /&gt;\r\nto think, to feel (HSK2)\"><ruby><span class=\"si\">觉得</span><span class=\"tr\">覺得</span><rt>jué de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"māma:&lt;br /&gt;\r\nMother (HSK1)\"><ruby><span class=\"si\">妈妈</span><span class=\"tr\">媽媽</span><rt>māma</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"kàn:&lt;br /&gt;\r\nlook (HSK1)\"><ruby><span class=\"si\">看</span><span class=\"tr\">看</span><rt>kàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qǐ lái:&lt;br /&gt;\r\n(complement) (HSK4)\"><ruby><span class=\"si\">起来</span><span class=\"tr\">起來</span><rt>qǐ lái</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn:&lt;br /&gt;\r\nvery (HSK1)\"><ruby><span class=\"si\">很</span><span class=\"tr\">很</span><rt>hěn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nián qīng:&lt;br /&gt;\r\nyoung (HSK3)\"><ruby><span class=\"si\">年轻</span><span class=\"tr\">年輕</span><rt>nián qīng</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"bàba:&lt;br /&gt;\r\ndad (HSK1)\"><ruby><span class=\"si\">爸爸</span><span class=\"tr\">爸爸</span><rt>bàba</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yě:&lt;br /&gt;\r\nalso (HSK2)\"><ruby><span class=\"si\">也</span><span class=\"tr\">也</span><rt>yě</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn:&lt;br /&gt;\r\nvery (HSK1)\"><ruby><span class=\"si\">很</span><span class=\"tr\">很</span><rt>hěn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gāo xìng:&lt;br /&gt;\r\nHappy (HSK1)\"><ruby><span class=\"si\">高兴</span><span class=\"tr\">高興</span><rt>gāo xìng</rt></ruby></abbr>。 <abbr rel=\"tooltip\" title=\"tā men:&lt;br /&gt;\r\nthey, them (HSK1)\"><ruby><span class=\"si\">他们</span><span class=\"tr\">他們</span><rt>tā men</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"kāi shǐ:&lt;br /&gt;\r\nstart (HSK2)\"><ruby><span class=\"si\">开始</span><span class=\"tr\">開始</span><rt>kāi shǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"cāi:&lt;br /&gt;\r\nGuess (HSK4)\"><ruby><span class=\"si\">猜</span><span class=\"tr\">猜</span><rt>cāi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ā yí:&lt;br /&gt;\r\nAunt (HSK3)\"><ruby><span class=\"si\">阿姨</span><span class=\"tr\">阿姨</span><rt>ā yí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"duō dà:&lt;br /&gt;\r\nhow old \"><ruby><span class=\"si\">多大</span><span class=\"tr\">多大</span><rt>duō dà</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nián jì:&lt;br /&gt;\r\nage (HSK5)\"><ruby><span class=\"si\">年纪</span><span class=\"tr\">年紀</span><rt>nián jì</rt></ruby></abbr>。 <abbr rel=\"tooltip\" title=\"ā yí:&lt;br /&gt;\r\nAunt (HSK3)\"><ruby><span class=\"si\">阿姨</span><span class=\"tr\">阿姨</span><rt>ā yí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shuō:&lt;br /&gt;\r\nsay \"><ruby><span class=\"si\">说</span><span class=\"tr\">說</span><rt>shuō</rt></ruby></abbr>， ” <abbr rel=\"tooltip\" title=\"nǐ men:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你们</span><span class=\"tr\">你們</span><rt>nǐ men</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"cāi:&lt;br /&gt;\r\nGuess (HSK4)\"><ruby><span class=\"si\">猜</span><span class=\"tr\">猜</span><rt>cāi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"cāi:&lt;br /&gt;\r\nGuess (HSK4)\"><ruby><span class=\"si\">猜</span><span class=\"tr\">猜</span><rt>cāi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"duō shǎo:&lt;br /&gt;\r\nhow many, how much (HSK1)\"><ruby><span class=\"si\">多少</span><span class=\"tr\">多少</span><rt>duō shǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"suì:&lt;br /&gt;\r\nage (HSK1)\"><ruby><span class=\"si\">岁</span><span class=\"tr\">歲</span><rt>suì</rt></ruby></abbr>？ ” <abbr rel=\"tooltip\" title=\"māma:&lt;br /&gt;\r\nMother (HSK1)\"><ruby><span class=\"si\">妈妈</span><span class=\"tr\">媽媽</span><rt>māma</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎng:&lt;br /&gt;\r\nthink (HSK1)\"><ruby><span class=\"si\">想</span><span class=\"tr\">想</span><rt>xiǎng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎng:&lt;br /&gt;\r\nthink (HSK1)\"><ruby><span class=\"si\">想</span><span class=\"tr\">想</span><rt>xiǎng</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"shuō:&lt;br /&gt;\r\nsay \"><ruby><span class=\"si\">说</span><span class=\"tr\">說</span><rt>shuō</rt></ruby></abbr>： ” <abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jué de:&lt;br /&gt;\r\nto think, to feel (HSK2)\"><ruby><span class=\"si\">觉得</span><span class=\"tr\">覺得</span><rt>jué de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"sì shí:&lt;br /&gt;\r\nforty \"><ruby><span class=\"si\">四十</span><span class=\"tr\">四十</span><rt>sì shí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"suì:&lt;br /&gt;\r\nage (HSK1)\"><ruby><span class=\"si\">岁</span><span class=\"tr\">歲</span><rt>suì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zuǒ yòu:&lt;br /&gt;\r\nabout (HSK6)\"><ruby><span class=\"si\">左右</span><span class=\"tr\">左右</span><rt>zuǒ yòu</rt></ruby></abbr>。 ” <abbr rel=\"tooltip\" title=\"ā yí:&lt;br /&gt;\r\nAunt (HSK3)\"><ruby><span class=\"si\">阿姨</span><span class=\"tr\">阿姨</span><rt>ā yí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiào:&lt;br /&gt;\r\nlaugh (HSK2)\"><ruby><span class=\"si\">笑</span><span class=\"tr\">笑</span><rt>xiào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"shuō:&lt;br /&gt;\r\nsay \"><ruby><span class=\"si\">说</span><span class=\"tr\">說</span><rt>shuō</rt></ruby></abbr>： ” <abbr rel=\"tooltip\" title=\"bù:&lt;br /&gt;\r\nno, not (HSK1)\"><ruby><span class=\"si\">不</span><span class=\"tr\">不</span><rt>bù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"duì:&lt;br /&gt;\r\nright, correct (HSK2)\"><ruby><span class=\"si\">对</span><span class=\"tr\">對</span><rt>duì</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jīn nián:&lt;br /&gt;\r\nThis year \"><ruby><span class=\"si\">今年</span><span class=\"tr\">今年</span><rt>jīn nián</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǔ shí:&lt;br /&gt;\r\nFifty \"><ruby><span class=\"si\">五十</span><span class=\"tr\">五十</span><rt>wǔ shí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"suì:&lt;br /&gt;\r\nage (HSK1)\"><ruby><span class=\"si\">岁</span><span class=\"tr\">歲</span><rt>suì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>。 ” <abbr rel=\"tooltip\" title=\"dà jiā:&lt;br /&gt;\r\nEveryone (HSK2)\"><ruby><span class=\"si\">大家</span><span class=\"tr\">大家</span><rt>dà jiā</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dōu:&lt;br /&gt;\r\nboth,all (HSK1)\"><ruby><span class=\"si\">都</span><span class=\"tr\">都</span><rt>dōu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gǎn dào:&lt;br /&gt;\r\nfeel \"><ruby><span class=\"si\">感到</span><span class=\"tr\">感到</span><rt>gǎn dào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jīng yà:&lt;br /&gt;\r\nsurprise (HSK6)\"><ruby><span class=\"si\">惊讶</span><span class=\"tr\">驚訝</span><rt>jīng yà</rt></ruby></abbr>。 <abbr rel=\"tooltip\" title=\"rán hòu:&lt;br /&gt;\r\nThen (HSK3)\"><ruby><span class=\"si\">然后</span><span class=\"tr\">然後</span><rt>rán hòu</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"tā men:&lt;br /&gt;\r\nthey, them (HSK1)\"><ruby><span class=\"si\">他们</span><span class=\"tr\">他們</span><rt>tā men</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yòu:&lt;br /&gt;\r\nagain (HSK3)\"><ruby><span class=\"si\">又</span><span class=\"tr\">又</span><rt>yòu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"liáo:&lt;br /&gt;\r\nchat \"><ruby><span class=\"si\">聊</span><span class=\"tr\">聊</span><rt>liáo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qǐ:&lt;br /&gt;\r\n(complement) \"><ruby><span class=\"si\">起</span><span class=\"tr\">起</span><rt>qǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shǔ xiàng:&lt;br /&gt;\r\nsign of the Zodiac \"><ruby><span class=\"si\">属相</span><span class=\"tr\">屬相</span><rt>shǔ xiàng</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"nǎ:&lt;br /&gt;\r\nwhich (HSK1)\"><ruby><span class=\"si\">哪</span><span class=\"tr\">哪</span><rt>nǎ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nián:&lt;br /&gt;\r\nYear (HSK1)\"><ruby><span class=\"si\">年</span><span class=\"tr\">年</span><rt>nián</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"chū shēng:&lt;br /&gt;\r\nborn (HSK4)\"><ruby><span class=\"si\">出生</span><span class=\"tr\">出生</span><rt>chū shēng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wèn tí:&lt;br /&gt;\r\nquestion, problem (HSK2)\"><ruby><span class=\"si\">问题</span><span class=\"tr\">問題</span><rt>wèn tí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yě:&lt;br /&gt;\r\nalso (HSK2)\"><ruby><span class=\"si\">也</span><span class=\"tr\">也</span><rt>yě</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"biàn:&lt;br /&gt;\r\nbecome \"><ruby><span class=\"si\">变</span><span class=\"tr\">變</span><rt>biàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux.) (HSK2)\"><ruby><span class=\"si\">得</span><span class=\"tr\">得</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yǒu qù:&lt;br /&gt;\r\ninteresting (HSK4)\"><ruby><span class=\"si\">有趣</span><span class=\"tr\">有趣</span><rt>yǒu qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qǐ lái:&lt;br /&gt;\r\n(complement) (HSK4)\"><ruby><span class=\"si\">起来</span><span class=\"tr\">起來</span><rt>qǐ lái</rt></ruby></abbr>。</p>\r\n</div>\r\n</div>', '2025-11-15 02:48:53'),
(59, 'congratulations', 'Congratulations', '恭喜你', 'https://traffic.libsyn.com/secure/learnchinese/3170.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/3170-r5kzlsqv5cfv5oq3rjsz2y5471dnfehvsmr7udfej6.jpg', '', 'HSK3', 'https://mandarinbean.com/congratulations/', '苏南铃美你去哪儿啊铃美我正打算去找你呢苏南找我铃美对啊今晚一起去吃饭吧我们给你庆祝庆祝苏南你们都知道了铃美我们早就知道了这是送给你的礼物祝你生日快乐天天开心苏南啊今天是我的生日你不说我都忘了谢谢你铃美原来你今天那么高兴不是因为过生日啊那是为什么苏南我通过应聘面试了下个星期开始去公司实习铃美那太好了什么工作苏南新媒体实习生我一直都对这方面挺感兴趣的之前还和同学创建了一个社交平台账号铃美那今天真是双喜临门那么短的时间你就能找到自己喜欢的工作真是太优秀了恭喜你真为你开心苏南哪里哪里我只是运气好罢了铃美走我们去王老师办公室大家都在那儿等你呢王老师今天还订了自助餐给你庆祝生日呢苏南好我要去告诉大家我通过面试了今天我请客', 'Sūnán Língměi nǐ qù nǎr a Língměi wǒ zhèng dǎ suàn qù zhǎo nǐ ne Sūnán zhǎo wǒ Língměi duì a jīn wǎn yī qǐ qù chī fàn ba wǒ men gěi nǐ qìng zhù qìng zhù Sūnán nǐ men dōu zhī dào le Língměi wǒ men zǎo jiù zhī dào le zhè shì sòng gěi nǐ de lǐ wù zhù nǐ shēng rì kuài lè tiān tiān kāi xīn Sūnán á jīn tiān shì wǒ de shēng rì nǐ bù shuō wǒ dōu wàng le xiè xiè nǐ Língměi yuán lái nǐ jīn tiān nà me gāo xìng bù shì yīn wèi guò shēng rì a nà shì wèi shén me Sūnán wǒ tōng guò yìng pìn miàn shì le xià gè xīng qī kāi shǐ qù gōng sī shí xí Língměi nà tài hǎo le shén me gōng zuò Sūnán xīn méi tǐ shí xí shēng wǒ yī zhí dōu duì zhè fāng miàn tǐng gǎn xìng qù de zhī qián hái hé tóng xué chuàng jiàn le yī gè shè jiāo píng tái zhàng hào Língměi nà jīn tiān zhēn shì shuāng xǐ lín mén nà me duǎn de shí jiān nǐ jiù néng zhǎo dào zì jǐ xǐ huān de gōng zuò zhēn shì tài yōu xiù le gōng xǐ nǐ zhēn wèi nǐ kāi xīn Sūnán nǎ lǐ nǎ lǐ wǒ zhǐ shì yùn qì hǎo bà le Língměi zǒu wǒ men qù Wáng lǎo shī bàn gōng shì dà jiā dōu zài nà ér děng nǐ ne Wáng lǎo shī jīn tiān hái dìng le zì zhù cān gěi nǐ qìng zhù shēng rì ne Sūnán hǎo wǒ yào qù gào sù dà jiā wǒ tōng guò miàn shì le jīn tiān wǒ qǐng kè', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"Sūnán:&lt;br /&gt;\r\nSunan \"><ruby><span class=\"si\">苏南</span><span class=\"tr\">蘇南</span><rt>Sūnán</rt></ruby></abbr>： <abbr rel=\"tooltip\" title=\"Língměi:&lt;br /&gt;\r\nSuzumi \"><ruby><span class=\"si\">铃美</span><span class=\"tr\">鈴美</span><rt>Língměi</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǎr:&lt;br /&gt;\r\nwhere (HSK1)\"><ruby><span class=\"si\">哪儿</span><span class=\"tr\">哪兒</span><rt>nǎr</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"a:&lt;br /&gt;\r\n（part.）used at the end of a sentence to indicate confirmation or defense (HSK3)\"><ruby><span class=\"si\">啊</span><span class=\"tr\">啊</span><rt>a</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Língměi:&lt;br /&gt;\r\nSuzumi \"><ruby><span class=\"si\">铃美</span><span class=\"tr\">鈴美</span><rt>Língměi</rt></ruby></abbr>： <abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhèng:&lt;br /&gt;\r\njust (HSK5)\"><ruby><span class=\"si\">正</span><span class=\"tr\">正</span><rt>zhèng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dǎ suàn:&lt;br /&gt;\r\nIntend (HSK3)\"><ruby><span class=\"si\">打算</span><span class=\"tr\">打算</span><rt>dǎ suàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhǎo:&lt;br /&gt;\r\nfind (HSK2)\"><ruby><span class=\"si\">找</span><span class=\"tr\">找</span><rt>zhǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ne:&lt;br /&gt;\r\n(aux. question mark) (HSK1)\"><ruby><span class=\"si\">呢</span><span class=\"tr\">呢</span><rt>ne</rt></ruby></abbr>！</p>\r\n<p><abbr rel=\"tooltip\" title=\"Sūnán:&lt;br /&gt;\r\nSunan \"><ruby><span class=\"si\">苏南</span><span class=\"tr\">蘇南</span><rt>Sūnán</rt></ruby></abbr>： <abbr rel=\"tooltip\" title=\"zhǎo:&lt;br /&gt;\r\nfind (HSK2)\"><ruby><span class=\"si\">找</span><span class=\"tr\">找</span><rt>zhǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Língměi:&lt;br /&gt;\r\nSuzumi \"><ruby><span class=\"si\">铃美</span><span class=\"tr\">鈴美</span><rt>Língměi</rt></ruby></abbr>： <abbr rel=\"tooltip\" title=\"duì:&lt;br /&gt;\r\nright (HSK2)\"><ruby><span class=\"si\">对</span><span class=\"tr\">對</span><rt>duì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"a:&lt;br /&gt;\r\n（part.）used at the end of a sentence to indicate confirmation or defense (HSK3)\"><ruby><span class=\"si\">啊</span><span class=\"tr\">啊</span><rt>a</rt></ruby></abbr>。 <abbr rel=\"tooltip\" title=\"jīn:&lt;br /&gt;\r\ntoday \"><ruby><span class=\"si\">今</span><span class=\"tr\">今</span><rt>jīn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǎn:&lt;br /&gt;\r\nNight \"><ruby><span class=\"si\">晚</span><span class=\"tr\">晚</span><rt>wǎn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī qǐ:&lt;br /&gt;\r\nTogether (HSK2)\"><ruby><span class=\"si\">一起</span><span class=\"tr\">一起</span><rt>yī qǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"chī:&lt;br /&gt;\r\neat (HSK1)\"><ruby><span class=\"si\">吃</span><span class=\"tr\">吃</span><rt>chī</rt></ru