INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(68, 'where-did-you-go-over-the-weekend', 'Where did you go over the weekend?', '周末去哪儿了？', 'https://traffic.libsyn.com/secure/learnchinese/3161.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/3161-qvoa9rlhzoz4qtvu6i6gz80zyy8v8i1yrbd3p2i15e.jpg', '', 'HSK3', 'https://mandarinbean.com/where-did-you-go-over-the-weekend/', '吴小宇姐周末你去哪儿了吴小咪周末我跟铃美一起去逛街了吴小宇你们买了很多东西吧吴小咪那还用说我们从上午一直逛到晚上都累得走不动了不过这一次没白去买了很多又便宜又好看的衣服吴小宇你们真能逛逛了一整天吴小咪逛街多好啊对我来说不但能买东西还能锻炼身体吴小宇这哪是锻炼身体啊吴小咪那你的周末是怎么过的吴小宇我周末跟同学去郊区漂流了吴小咪水春河那儿不是很多老年人爱去吗吴小宇哪儿啊年轻人也很多最近水量大漂流特别刺激吴小咪漂流难不难吴小宇不难你不怕衣服湿了就行这周末我们一起去吴小咪我想想吧吴小宇真不难我们叫上哥哥一起去你坐中间我和哥哥划船吴小咪不是我是怕被晒黑', 'Wú Xiǎoyǔ jiě zhōu mò nǐ qù nǎr le Wú Xiǎomī zhōu mò wǒ gēn Língměi yī qǐ qù guàng jiē le Wú Xiǎoyǔ nǐ men mǎi le hěn duō dōngxi ba Wú Xiǎomī nà hái yòng shuō wǒ men cóng shàng wǔ yī zhí guàng dào wǎn shàng dōu lèi de zǒu bù dòng le bù guò zhè yī cì méi bái qù mǎi le hěn duō yòu piányi yòu hǎo kàn de yī fú Wú Xiǎoyǔ nǐ men zhēn néng guàng guàng le yī zhěng tiān Wú Xiǎomī guàng jiē duō hǎo a duì wǒ lái shuō bù dàn néng mǎi dōngxi hái néng duàn liàn shēn tǐ Wú Xiǎoyǔ zhè nǎ shì duàn liàn shēn tǐ a Wú Xiǎomī nà nǐ de zhōu mò shì zěn me guò de Wú Xiǎoyǔ wǒ zhōu mò gēn tóng xué qù jiāo qū piāo liú le Wú Xiǎomī shuǐ chūn hé nàr bù shì hěn duō lǎo nián rén ài qù ma Wú Xiǎoyǔ nǎr a nián qīng rén yě hěn duō zuì jìn shuǐ liàng dà piāo liú tè bié cì jī Wú Xiǎomī piāo liú nán bù nán Wú Xiǎoyǔ bù nán nǐ bù pà yī fú shī le jiù xíng zhè zhōu mò wǒ men yī qǐ qù Wú Xiǎomī wǒ xiǎng xiǎng ba Wú Xiǎoyǔ zhēn bù nán wǒ men jiào shàng gēge yī qǐ qù nǐ zuò zhōng jiān wǒ hé gēge huá chuán Wú Xiǎomī bù shì wǒ shì pà bèi shài hēi', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎoyǔ:&lt;br /&gt;\r\nWu Xiaoyu \"><ruby><span class=\"si\">吴小宇</span><span class=\"tr\">吳小宇</span><rt>Wú Xiǎoyǔ</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"jiě:&lt;br /&gt;\r\nsister \"><ruby><span class=\"si\">姐</span><span class=\"tr\">姐</span><rt>jiě</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"zhōu mò:&lt;br /&gt;\r\nweekend (HSK3)\"><ruby><span class=\"si\">周末</span><span class=\"tr\">周末</span><rt>zhōu mò</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǎr:&lt;br /&gt;\r\nwhere (HSK1)\"><ruby><span class=\"si\">哪儿</span><span class=\"tr\">哪兒</span><rt>nǎr</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎomī:&lt;br /&gt;\r\nWu Xiaomi \"><ruby><span class=\"si\">吴小咪</span><span class=\"tr\">吳小咪</span><rt>Wú Xiǎomī</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"zhōu mò:&lt;br /&gt;\r\nweekend (HSK3)\"><ruby><span class=\"si\">周末</span><span class=\"tr\">周末</span><rt>zhōu mò</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gēn:&lt;br /&gt;\r\nand, with (HSK3)\"><ruby><span class=\"si\">跟</span><span class=\"tr\">跟</span><rt>gēn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Língměi:&lt;br /&gt;\r\nSuzumi \"><ruby><span class=\"si\">铃美</span><span class=\"tr\">鈴美</span><rt>Língměi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī qǐ:&lt;br /&gt;\r\nTogether (HSK2)\"><ruby><span class=\"si\">一起</span><span class=\"tr\">一起</span><rt>yī qǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"guàng jiē:&lt;br /&gt;\r\nshopping, lounging around \"><ruby><span class=\"si\">逛街</span><span class=\"tr\">逛街</span><rt>guàng jiē</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>。</p>\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎoyǔ:&lt;br /&gt;\r\nWu Xiaoyu \"><ruby><span class=\"si\">吴小宇</span><span class=\"tr\">吳小宇</span><rt>Wú Xiǎoyǔ</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"nǐ men:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你们</span><span class=\"tr\">你們</span><rt>nǐ men</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"mǎi:&lt;br /&gt;\r\npurchase (HSK1)\"><ruby><span class=\"si\">买</span><span class=\"tr\">買</span><rt>mǎi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn duō:&lt;br /&gt;\r\na lot of \"><ruby><span class=\"si\">很多</span><span class=\"tr\">很多</span><rt>hěn duō</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dōngxi:&lt;br /&gt;\r\nthing, stuff (HSK1)\"><ruby><span class=\"si\">东西</span><span class=\"tr\">東西</span><rt>dōngxi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ba:&lt;br /&gt;\r\n(part. )used at the end of a sentense to indicate consultation, suggestion, request or command (HSK2)\"><ruby><span class=\"si\">吧</span><span class=\"tr\">吧</span><rt>ba</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎomī:&lt;br /&gt;\r\nWu Xiaomi \"><ruby><span class=\"si\">吴小咪</span><span class=\"tr\">吳小咪</span><rt>Wú Xiǎomī</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"nà hái yòng shuō:&lt;br /&gt;\r\nof course \"><ruby><span class=\"si\">那还用说</span><span class=\"tr\">那還用說</span><rt>nà hái yòng shuō</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"wǒ men:&lt;br /&gt;\r\nwe, us (HSK1)\"><ruby><span class=\"si\">我们</span><span class=\"tr\">我們</span><rt>wǒ men</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"cóng:&lt;br /&gt;\r\nfrom (HSK2)\"><ruby><span class=\"si\">从</span><span class=\"tr\">從</span><rt>cóng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shàng wǔ:&lt;br /&gt;\r\nmorning (HSK1)\"><ruby><span class=\"si\">上午</span><span class=\"tr\">上午</span><rt>shàng wǔ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī zhí:&lt;br /&gt;\r\nall the way (HSK3)\"><ruby><span class=\"si\">一直</span><span class=\"tr\">一直</span><rt>yī zhí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"guàng:&lt;br /&gt;\r\nlounge around (HSK4)\"><ruby><span class=\"si\">逛</span><span class=\"tr\">逛</span><rt>guàng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dào:&lt;br /&gt;\r\nto arrive,to reach (HSK2)\"><ruby><span class=\"si\">到</span><span class=\"tr\">到</span><rt>dào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǎn shàng:&lt;br /&gt;\r\nnight (HSK2)\"><ruby><span class=\"si\">晚上</span><span class=\"tr\">晚上</span><rt>wǎn shàng</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"dōu:&lt;br /&gt;\r\nboth,all (HSK1)\"><ruby><span class=\"si\">都</span><span class=\"tr\">都</span><rt>dōu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"lèi:&lt;br /&gt;\r\ntired (HSK2)\"><ruby><span class=\"si\">累</span><span class=\"tr\">累</span><rt>lèi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(particle） (HSK2)\"><ruby><span class=\"si\">得</span><span class=\"tr\">得</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zǒu:&lt;br /&gt;\r\nWalk (HSK2)\"><ruby><span class=\"si\">走</span><span class=\"tr\">走</span><rt>zǒu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bù:&lt;br /&gt;\r\nno, not (HSK1)\"><ruby><span class=\"si\">不</span><span class=\"tr\">不</span><rt>bù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dòng:&lt;br /&gt;\r\nmove (complement) \"><ruby><span class=\"si\">动</span><span class=\"tr\">動</span><rt>dòng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"bù guò:&lt;br /&gt;\r\nbut (HSK4)\"><ruby><span class=\"si\">不过</span><span class=\"tr\">不過</span><rt>bù guò</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"zhè:&lt;br /&gt;\r\nthis (HSK1)\"><ruby><span class=\"si\">这</span><span class=\"tr\">這</span><rt>zhè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī:&lt;br /&gt;\r\none (HSK1)\"><ruby><span class=\"si\">一</span><span class=\"tr\">一</span><rt>yī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"cì:&lt;br /&gt;\r\ntime (measure word) (HSK2)\"><ruby><span class=\"si\">次</span><span class=\"tr\">次</span><rt>cì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"méi:&lt;br /&gt;\r\nno, not (HSK1)\"><ruby><span class=\"si\">没</span><span class=\"tr\">沒</span><rt>méi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bái:&lt;br /&gt;\r\nin vain (HSK2)\"><ruby><span class=\"si\">白</span><span class=\"tr\">白</span><rt>bái</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"mǎi:&lt;br /&gt;\r\npurchase (HSK1)\"><ruby><span class=\"si\">买</span><span class=\"tr\">買</span><rt>mǎi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn duō:&lt;br /&gt;\r\na lot of \"><ruby><span class=\"si\">很多</span><span class=\"tr\">很多</span><rt>hěn duō</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yòu:&lt;br /&gt;\r\n又……又…… It indicates two quality or situations exist at the same time. (HSK3)\"><ruby><span class=\"si\">又</span><span class=\"tr\">又</span><rt>yòu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"piányi:&lt;br /&gt;\r\nCheap (HSK2)\"><ruby><span class=\"si\">便宜</span><span class=\"tr\">便宜</span><rt>piányi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yòu:&lt;br /&gt;\r\n又……又…… It indicates two quality or situations exist at the same time. (HSK3)\"><ruby><span class=\"si\">又</span><span class=\"tr\">又</span><rt>yòu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hǎo kàn:&lt;br /&gt;\r\nnice \"><ruby><span class=\"si\">好看</span><span class=\"tr\">好看</span><rt>hǎo kàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī fú:&lt;br /&gt;\r\nclothes (HSK1)\"><ruby><span class=\"si\">衣服</span><span class=\"tr\">衣服</span><rt>yī fú</rt></ruby></abbr>。</p>\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎoyǔ:&lt;br /&gt;\r\nWu Xiaoyu \"><ruby><span class=\"si\">吴小宇</span><span class=\"tr\">吳小宇</span><rt>Wú Xiǎoyǔ</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"nǐ men:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你们</span><span class=\"tr\">你們</span><rt>nǐ men</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhēn:&lt;br /&gt;\r\nreal (HSK2)\"><ruby><span class=\"si\">真</span><span class=\"tr\">真</span><rt>zhēn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"néng:&lt;br /&gt;\r\nable (HSK1)\"><ruby><span class=\"si\">能</span><span class=\"tr\">能</span><rt>néng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"guàng:&lt;br /&gt;\r\nlounge around (HSK4)\"><ruby><span class=\"si\">逛</span><span class=\"tr\">逛</span><rt>guàng</rt></ruby></abbr>！<abbr rel=\"tooltip\" title=\"guàng:&lt;br /&gt;\r\nlounge around (HSK4)\"><ruby><span class=\"si\">逛</span><span class=\"tr\">逛</span><rt>guàng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī:&lt;br /&gt;\r\none (HSK1)\"><ruby><span c