INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(71, 'book-a-hotel', 'Book a hotel', '预订酒店', 'https://traffic.libsyn.com/secure/learnchinese/3158.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/3158-qsz20ih4glt2lzcspt8aypw1bftf1t1x3f1zyrodaq.jpg', '', 'HSK3', 'https://mandarinbean.com/book-a-hotel/', '杨欢欢大龙你订酒店了吗大龙还没有我现在订吧你们也一起帮我看看杨欢欢好啊我记得我们家附近有家酒店挺不错的大龙是吗那家酒店叫什么我在手机上搜一搜杨欢欢叫索菲特你看看还有房间吗大龙有有单人房双床房和大床房我订一间单人房就行了杨欢欢上次我叔叔来住的就是这家酒店他说酒店的中央空调温度合适房间和各种用品又干净又齐全不但服务很好酒店早餐的种类也很多信号很稳定大龙听起来真不错我现在就订杨达达多少钱一晚啊大龙单人房元一晚我订了七个晚上杨达达索菲特酒店不远开车十分钟就到了一会儿吃完饭我们送你过去大龙好的谢谢', 'Yáng Huānhuān Dàlóng nǐ dìng jiǔ diàn le ma Dàlóng hái méi yǒu wǒ xiàn zài dìng ba nǐ men yě yī qǐ bāng wǒ kàn kàn Yáng Huānhuān hǎo a wǒ jì de wǒ men jiā fù jìn yǒu jiā jiǔ diàn tǐng bù cuò de Dàlóng shì ma nà jiā jiǔ diàn jiào shén me wǒ zài shǒu jī shàng sōu yī sōu Yáng Huānhuān jiào Suǒfēitè nǐ kàn kàn hái yǒu fáng jiān ma Dàlóng yǒu yǒu dān rén fáng shuāng chuáng fáng hé dà chuáng fáng wǒ dìng yī jiān dān rén fáng jiù xíng le Yáng Huānhuān shàng cì wǒ shū shū lái zhù de jiù shì zhè jiā jiǔ diàn tā shuō jiǔ diàn de zhōng yāng kōng tiáo wēn dù hé shì fáng jiān hé gè zhǒng yòng pǐn yòu gān jìng yòu qí quán bù dàn fú wù hěn hǎo jiǔ diàn zǎo cān de zhǒng lèi yě hěn duō xìn hào hěn wěn dìng Dàlóng tīng qǐ lái zhēn bù cuò wǒ xiàn zài jiù dìng Yáng Dádá duō shǎo qián yī wǎn a Dàlóng dān rén fáng yuán yī wǎn wǒ dìng le qī gè wǎn shàng Yáng Dádá Suǒfēitè jiǔ diàn bù yuǎn kāi chē shí fēn zhōng jiù dào le yī huìr chī wán fàn wǒ men sòng nǐ guò qù Dàlóng hǎo de xiè xiè', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"Yáng Huānhuān:&lt;br /&gt;\r\nYang Huanhuan \"><ruby><span class=\"si\">杨欢欢</span><span class=\"tr\">楊歡歡</span><rt>Yáng Huānhuān</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"Dàlóng:&lt;br /&gt;\r\nDalong \"><ruby><span class=\"si\">大龙</span><span class=\"tr\">大龍</span><rt>Dàlóng</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dìng:&lt;br /&gt;\r\norder \"><ruby><span class=\"si\">订</span><span class=\"tr\">訂</span><rt>dìng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jiǔ diàn:&lt;br /&gt;\r\nhotel \"><ruby><span class=\"si\">酒店</span><span class=\"tr\">酒店</span><rt>jiǔ diàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ma:&lt;br /&gt;\r\n(aux. question mark) (HSK1)\"><ruby><span class=\"si\">吗</span><span class=\"tr\">嗎</span><rt>ma</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Dàlóng:&lt;br /&gt;\r\nDalong \"><ruby><span class=\"si\">大龙</span><span class=\"tr\">大龍</span><rt>Dàlóng</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"hái:&lt;br /&gt;\r\nyet (HSK2)\"><ruby><span class=\"si\">还</span><span class=\"tr\">還</span><rt>hái</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"méi yǒu:&lt;br /&gt;\r\nNo \"><ruby><span class=\"si\">没有</span><span class=\"tr\">沒有</span><rt>méi yǒu</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiàn zài:&lt;br /&gt;\r\nnow (HSK1)\"><ruby><span class=\"si\">现在</span><span class=\"tr\">現在</span><rt>xiàn zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dìng:&lt;br /&gt;\r\norder \"><ruby><span class=\"si\">订</span><span class=\"tr\">訂</span><rt>dìng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ba:&lt;br /&gt;\r\n(part. )used at the end of a sentense to indicate consultation, suggestion, request or command (HSK2)\"><ruby><span class=\"si\">吧</span><span class=\"tr\