INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(84, 'age-discrimination', 'Age Discrimination', '年龄歧视', 'https://traffic.libsyn.com/secure/learnchinese/4180.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/4180-ra8dr5553osb61bgon14tk0bh93tmylgglc130c11u.jpg', '', 'HSK4', 'https://mandarinbean.com/age-discrimination/', '最近广州出现了一个招聘环卫工人的广告居然要求年龄在岁以下这个广告引起了大家的愤怒认为这是严重的年龄歧视招聘方说这是因为工作内容对体力要求很高需要上夜班等但是因为人们的反对这个招聘广告修改了年龄限制变成了从岁到法定退休年龄都可以申请', 'zuì jìn Guǎngzhōu chū xiàn le yī gè zhāo pìn huán wèi gōng rén de guǎng gào jū rán yāo qiú nián líng zài suì yǐ xià zhè gè guǎng gào yǐn qǐ le dà jiā de fèn nù rèn wéi zhè shì yán zhòng de nián líng qí shì zhāo pìn fāng shuō zhè shì yīn wèi gōng zuò nèi róng duì tǐ lì yāo qiú hěn gāo xū yào shàng yè bān děng dàn shì yīn wèi rén men de fǎn duì zhè gè zhāo pìn guǎng gào xiū gǎi le nián líng xiàn zhì biàn chéng le cóng suì dào fǎ dìng tuì xiū nián líng dōu kě yǐ shēn qǐng', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"zuì jìn:&lt;br /&gt;\r\nrecently (HSK3)\"><ruby><span class=\"si\">最近</span><span class=\"tr\">最近</span><rt>zuì jìn</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"Guǎngzhōu:&lt;br /&gt;\r\nGuangzhou \"><ruby><span class=\"si\">广州</span><span class=\"tr\">廣州</span><rt>Guǎngzhōu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"chū xiàn:&lt;br /&gt;\r\nappeared (HSK3)\"><ruby><span class=\"si\">出现</span><span class=\"tr\">出現</span><rt>chū xiàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī:&lt;br /&gt;\r\none (HSK1)\"><ruby><span class=\"si\">一</span><span class=\"tr\">一</span><rt>yī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gè:&lt;br /&gt;\r\n(