INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(91, 'my-stuff-is-lost', 'My stuff is lost', '我的东西不见了', 'https://traffic.libsyn.com/secure/learnchinese/4171.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/4171-r04m7mdmr7mewtiydb9oaod78qhz36divly1hcetea.jpg', '', 'HSK4', 'https://mandarinbean.com/my-stuff-is-lost/', '吴小宇苏南你去哪儿啊这么着急苏南小宇在这儿遇到你太好了我正要去找你呢吴小宇怎么了苏南我的学生卡不见了我该怎么办啊吴小宇你别着急宿舍和教室你都去找过了吗苏南宿舍教室和图书馆我都找过了可是都没找到吴小宇什么时候不见的苏南我不知道我昨天下午去图书馆借书的时候都还在吴小宇后来你去哪儿了苏南后来去了食堂吃饭但是没刷学生卡我付的现金吴小宇那卡号你记得吗苏南不记得了不过我手机里有学生卡的照片小宇我要不要报警啊吴小宇目前不用报警再说了你学生卡里的钱也不多我们自己找就可以了你把学生卡的照片发给我我发到朋友圈看看有没有同学捡到苏南好吴小宇现在我们先打印一个寻物启事然后把它贴在公告栏上苏南寻物启事是什么吴小宇寻物启事就是寻找丢失的东西的告示一般要写清楚丢了什么在哪儿丢的什么时候丢的以及失主的联系方式但是由于你不知道什么时候丢的在哪儿丢的我们可以把你的学生卡图片放上去再写上你的名字和电话号码就行了苏南明白了那如果没有人捡到呢吴小宇那我们下午就去学生管理中心请管理老师把你丢的那张卡注销重新给你办一张新的卡苏南好那我们赶紧去打印寻物启事吧吴小宇我有同学在学校的失物招领中心做志愿者一会儿我问问他们那儿有没有你的学生卡苏南失物招领中心是丢了东西的地方吗吴小宇有人捡到了东西但是不知道谁是失主就会送去失物招领中心失主可以去那儿看看能不能找到丢了的东西苏南明白了谢谢你小宇还好有你帮我吴小宇不客气', 'Wú Xiǎoyǔ Sūnán nǐ qù nǎr a zhè me zháo jí Sūnán Xiǎoyǔ zài zhèr yù dào nǐ tài hǎo le wǒ zhèng yào qù zhǎo nǐ ne Wú Xiǎoyǔ zěn me le Sūnán wǒ de xué shēng kǎ bù jiàn le wǒ gāi zěn me bàn a Wú Xiǎoyǔ nǐ bié zháo jí sù shè hé jiào shì nǐ dōu qù zhǎo guò le ma Sūnán sù shè jiào shì hé tú shū guǎn wǒ dōu zhǎo guò le kě shì dōu méi zhǎo dào Wú Xiǎoyǔ shénme shí hòu bù jiàn de Sūnán wǒ bù zhī dào wǒ zuó tiān xià wǔ qù tú shū guǎn jiè shū de shí hòu dōu hái zài Wú Xiǎoyǔ hòu lái nǐ qù nǎr le Sūnán hòu lái qù le shí táng chī fàn dàn shì méi shuā xué shēng kǎ wǒ fù de xiàn jīn Wú Xiǎoyǔ nà kǎ hào nǐ jì dé ma Sūnán bù jì dé le bù guò wǒ shǒu jī lǐ yǒu xué shēng kǎ de zhào piàn Xiǎoyǔ wǒ yào bù yào bào jǐng a Wú Xiǎoyǔ mù qián bù yòng bào jǐng zài shuō le nǐ xué shēng kǎ lǐ de qián yě bù duō wǒ men zì jǐ zhǎo jiù kě yǐ le nǐ bǎ xué shēng kǎ de zhào piàn fā gěi wǒ wǒ fā dào péng yǒu quān kàn kàn yǒu méi yǒu tóng xué jiǎn dào Sūnán hǎo Wú Xiǎoyǔ xiàn zài wǒ men xiān dǎ yìn yī gè xún wù qǐ shì rán hòu bǎ tā tiē zài gōng gào lán shàng Sūnán xún wù qǐ shì shì shén me Wú Xiǎoyǔ xún wù qǐ shì jiù shì xún zhǎo diū shī de dōng xī de gào shì yī bān yào xiě qīng chǔ diū le shén me zài nǎr diū de shén me shí hòu diū de yǐ jí shī zhǔ de lián xì fāng shì dàn shì yóu yú nǐ bù zhī dào shén me shí hòu diū de zài nǎr diū de wǒ men kě yǐ bǎ nǐ de xué shēng kǎ tú piàn fàng shàng qù zài xiě shàng nǐ de míng zì hé diàn huà hào mǎ jiù xíng le Sūnán míng bái le nà rú guǒ méi yǒu rén jiǎn dào ne Wú Xiǎoyǔ nà wǒ men xià wǔ jiù qù xué shēng guǎn lǐ zhōng xīn qǐng guǎn lǐ lǎo shī bǎ nǐ diū de nà zhāng kǎ zhù xiāo chóng xīn gěi nǐ bàn yī zhāng xīn de kǎ Sūnán hǎo nà wǒ men gǎn jǐn qù dǎ yìn xún wù qǐ shì ba Wú Xiǎoyǔ wǒ yǒu tóng xué zài xué xiào de shī wù zhāo lǐng zhōng xīn zuò zhì yuàn zhě yī huìr wǒ wèn wèn tā men nàr yǒu méi yǒu nǐ de xué shēng kǎ Sūnán shī wù zhāo lǐng zhōng xīn shì diū le dōngxi de dì fāng ma Wú Xiǎoyǔ yǒu rén jiǎn dào le dōngxi dàn shì bù zhī dào shéi shì shī zhǔ jiù huì sòng qù shī wù zhāo lǐng zhōng xīn shī zhǔ kě yǐ qù nàr kàn kàn néng bù néng zhǎo dào diū le de dōngxi Sūnán míng bái le xièxie nǐ Xiǎoyǔ hái hǎo yǒu nǐ bāng wǒ Wú Xiǎoyǔ bù kè qì', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎoyǔ:&lt;br /&gt;\r\nWu Xiaoyu \"><ruby><span class=\"si\">吴小宇</span><span class=\"tr\">吳小宇</span><rt>Wú Xiǎoyǔ</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"Sūnán:&lt;br /&gt;\r\nSunan \"><ruby><span class=\"si\">苏南</span><span class=\"tr\">蘇南</span><rt>Sūnán</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǎr:&lt;br /&gt;\r\nwhere (HSK1)\"><ruby><span class=\"si\">哪儿</span><span class=\"tr\">哪兒</span><rt>nǎr</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"a:&lt;br /&gt;\r\n（part.）used at the end of a sentence to indicate confirmation or defense (HSK3)\"><ruby><span class=\"si\">啊</span><span class=\"tr\">啊</span><rt>a</rt></ruby></abbr>？<abbr rel=\"tooltip\" title=\"zhè me:&lt;br /&gt;\r\nso \"><ruby><span class=\"si\">这么</span><span class=\"tr\">這麽</span><rt>zhè me</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zháo jí:&lt;br /&gt;\r\nin a hurry (HSK3)\"><ruby><span class=\"si\">着急</span><span class=\"tr\">著急</span><rt>zháo jí</rt></ruby></abbr>！</p>\r\n<p><abbr rel=\"tooltip\" title=\"Sūnán:&lt;br /&gt;\r\nSunan \"><ruby><span class=\"si\">苏南</span><span class=\"tr\">蘇南</span><rt>Sūnán</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"Xiǎoyǔ:&lt;br /&gt;\r\nXiaoyu \"><ruby><span class=\"si\">小宇</span><span class=\"tr\">小宇</span><rt>Xiǎoyǔ</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"zài:&lt;br /&gt;\r\n(located) at / (to be) in (HSK1)\"><ruby><span class=\"si\">在</span><span class=\"tr\">在</span><rt>zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhèr:&lt;br /&gt;\r\nhere (HSK1)\"><ruby><span class=\"si\">这儿</span><span class=\"tr\">這兒</span><rt>zhèr</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yù dào:&lt;br /&gt;\r\nmeet (HSK3)\"><ruby><span class=\"si\">遇到</span><span class=\"tr\">遇到</span><rt>yù dào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"tài:&lt;br /&gt;\r\ntoo (HSK1)\"><ruby><span class=\"si\">太</span><span class=\"tr\">太</span><rt>tài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hǎo:&lt;br /&gt;\r\ngood, well (HSK1)\"><ruby><span class=\"si\">好</span><span class=\"tr\">好</span><rt>hǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhèng:&lt;br /&gt;\r\njust (HSK5)\"><ruby><span class=\"si\">正</span><span class=\"tr\">正</span><rt>zhèng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yào:&lt;br /&gt;\r\nto want to, would like to (HSK2)\"><ruby><span class=\"si\">要</span><span class=\"tr\">要</span><rt>yào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhǎo:&lt;br /&gt;\r\nfind (HSK2)\"><ruby><span class=\"si\">找</span><span class=\"tr\">找</span><rt>zhǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ne:&lt;br /&gt;\r\n(aux. question mark) (HSK1)\"><ruby><span class=\"si\">呢</span><span class=\"tr\">呢</span><rt>ne</rt></ruby></abbr>！</p>\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎoyǔ:&lt;br /&gt;\r\nWu Xiaoyu \"><ruby><span class=\"si\">吴小宇</span><span class=\"tr\">吳小宇</span><rt>Wú Xiǎoyǔ</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"zěn me:&lt;br /&gt;\r\nwhy (HSK1)\"><ruby><span class=\"si\">怎么</span><span class=\"tr\">怎麽</span><rt>zěn me</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Sūnán:&lt;br /&gt;\r\nSunan \"><ruby><span class=\"si\">苏南</span><span class=\"tr\">蘇南</span><rt>Sūnán</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xué shēng:&lt;br /&gt;\r\nstudent (HSK1)\"><ruby><span class=\"si\">学生</span><span class=\"tr\">學生</span><rt>xué shēng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"kǎ:&lt;br /&gt;\r\nCard \"><ruby><span class=\"si\">卡</span><span class=\"tr\">卡</span><rt>kǎ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bù jiàn:&lt;br /&gt;\r\nlost, missing \"><ruby><span class=\"si\">不见</span><span class=\"tr\">不見</span><rt>bù jiàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gāi:&lt;br /&gt;\r\nShould \"><ruby><span class=\"si\">该</span><span class=\"tr\">該</span><rt>gāi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zěn me bàn:&lt;br /&gt;\r\nwhat to do \"><ruby><span class=\"si\">怎么办</span><span class=\"tr\">怎麽辦</span><rt>zěn me bàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"a:&lt;br /&gt;\r\n（part.）used at the end of a sentence to indicate confirmation or defense (HSK3)\"><ruby><span class=\"si\">啊</span><span class=\"tr\">啊</span><rt>a</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎoyǔ:&lt;br /&gt;\r\nWu Xiaoyu \"><ruby><span class=\"si\">吴小宇</span><span class=\"tr\">吳小宇</span><rt>Wú Xiǎoyǔ</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bié:&lt;br /&gt;\r\nDon\'t (HSK2)\"><ruby><span class=\"si\">别</span><span class=\"tr\">別</span><rt>bié</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zháo jí:&lt;br /&gt;\r\nin a hurry (HSK3)\"><ruby><span class=\"si\">着急</span><span class=\"tr\">著急</span><rt>zháo jí