INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(110, 'buy-clothes-1', 'Buy clothes (1)', '买衣服（1）', 'https://traffic.libsyn.com/secure/learnchinese/4153.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/4153-qlvb56rlnfemo936avr85ap5g5htps5anh0orbxh76.jpg', '', 'HSK4', 'https://mandarinbean.com/buy-clothes-1/', '吴小咪铃美你觉得这条红色的裙子怎么样铃美颜色还不错就是有点大吴小咪麻烦给我换小一号的售货员不好意思女士这是上周新到的红色的只有这一件了绿色的有小码您要试一下吗吴小咪我不喜欢绿色算了我试试那条蓝色的吧铃美这条很适合你吴小咪会不会有点薄秋天穿冷不冷服务员我们还有一款外套跟这条裙子搭配保暖又时尚两件一起买还可以打九五折吴小咪我看看铃美小咪你先试试我奶茶喝多了想上厕所你们这里有卫生间吗服务员女士店里没有卫生间您出门往左然后一直走到头有一个卫生间铃美谢谢我马上回来', 'Wú Xiǎomī Língměi nǐ jué de zhè tiáo hóng sè de qún zi zěn me yàng Língměi yán sè hái bù cuò jiù shì yǒu diǎn dà Wú Xiǎomī má fán gěi wǒ huàn xiǎo yī hào de shòu huò yuán bù hǎo yì sī nǚ shì zhè shì shàng zhōu xīn dào de hóng sè de zhǐ yǒu zhè yī jiàn le lǜ sè de yǒu xiǎo mǎ nín yào shì yī xià ma Wú Xiǎomī wǒ bù xǐ huān lǜ sè suàn le wǒ shì shì nà tiáo lán sè de ba Língměi zhè tiáo hěn shì hé nǐ Wú Xiǎomī huì bù huì yǒu diǎn báo qiū tiān chuān lěng bù lěng fú wù yuán wǒ men hái yǒu yī kuǎn wài tào gēn zhè tiáo qún zi dā pèi bǎo nuǎn yòu shí shàng liǎng jiàn yī qǐ mǎi hái kě yǐ dǎ jiǔ wǔ zhé Wú Xiǎomī wǒ kàn kàn Língměi Xiǎomī nǐ xiān shì shì wǒ nǎi chá hē duō le xiǎng shàng cè suǒ nǐ men zhè lǐ yǒu wèi shēng jiān ma fú wù yuán nǚ shì diàn lǐ méi yǒu wèi shēng jiān nín chū mén wǎng zuǒ rán hòu yī zhí zǒu dào tóu yǒu yī gè wèi shēng jiān Língměi xiè xiè wǒ mǎ shàng huí lái', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎomī:&lt;br /&gt;\r\nWu Xiaomi\"><ruby><span class=\"si\">吴小咪</span><span class=\"tr\">吳小咪</span><rt>Wú Xiǎomī</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"Língměi:&lt;br /&gt;\r\nSuzumi\"><ruby><span class=\"si\">铃美</span><span class=\"tr\">鈴美</span><rt>Língměi</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jué de:&lt;br /&gt;\r\nto think, to feel (HSK2)\"><ruby><span class=\"si\">觉得</span><span class=\"tr\">覺得</span><rt>jué de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhè:&lt;br /&gt;\r\nthis (HSK1)\"><ruby><span class=\"si\">这</span><span class=\"tr\">這</span><rt>zhè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"tiáo:&lt;br /&gt;\r\n(measure word) (HSK3)\"><ruby><span class=\"si\">条</span><span class=\"tr\">條</span><rt>tiáo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hóng sè:&lt;br /&gt;\r\nred\"><ruby><span class=\"si\">红色</span><span class=\"tr\">紅色</span><rt>hóng sè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qún zi:&lt;br /&gt;\r\nskirt (HSK3)\"><ruby><span class=\"si\">裙子</span><span class=\"tr\">裙子</span><rt>qún zi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zěn me yàng:&lt;br /&gt;\r\nHow about it (HSK1)\"><ruby><span class=\"si\">怎么样</span><span class=\"tr\">怎麽樣</span><rt>zěn me yàng</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Língměi:&lt;br /&gt;\r\nSuzumi\"><ruby><span class=\"si\">铃美</span><span class=\"tr\">鈴美</span><rt>Língměi</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"yán sè:&lt;br /&gt;\r\ncolor (HSK2)\"><ruby><span class=\"si\">颜色</span><span class=\"tr\">顔色</span><rt>yán sè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hái:&lt;br /&gt;\r\nstill (HSK2)\"><ruby><span class=\"si\">还</span><span class=\"tr\">還</span><rt>hái</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bù cuò:&lt;br /&gt;\r\ngood\"><ruby><span class=\"si\">不错</span><span class=\"tr\">不錯</span><rt>bù cuò</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"jiù:&lt;br /&gt;\r\njust, with regard to (HSK2)\"><ruby><span class=\"si\">就</