INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(121, 'encoffin-cafe', 'Encoffin Café', '入殓咖啡馆', 'https://traffic.libsyn.com/secure/learnchinese/5157.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/5157-qyjkmgpy9o6h1nr2q10fbfx0ypwkqmqv896wrfwr4i.jpg', '', 'HSK5', 'https://mandarinbean.com/encoffin-cafe/', '很多人会想象婚礼的样子但是很少有人去思考葬礼你想象过你的死亡和葬礼吗你想思考生命的意义和价值吗或许你可以试试位于日本千叶县富津市的入殓咖啡馆这是日本一家老字号殡葬公司开的咖啡馆为消费者提供躺入棺材的体验服务消费者花费大约两千两百日元就能使用这项服务盖上棺材盖思考人生并且打卡拍照听起来不太吉利但是棺材上有花卉等新颖的设计减少了人们的抵触情绪该公司推出此服务的目的是让更多人思考死亡和葬礼同时也和年轻人们建立联系探索新的殡葬形式这也是一个契机可以让人重新审视与他人的关系静静思考在寿命结束前应该如何生活此外该公司也希望能通过咖啡馆的活动改变年轻人对殡葬业的刻板印象从而振兴整个行业的发展', 'hěn duō rén huì xiǎng xiàng hūn lǐ de yàng zi dàn shì hěn shǎo yǒu rén qù sī kǎo zàng lǐ nǐ xiǎng xiàng guò nǐ de sǐ wáng hé zàng lǐ ma nǐ xiǎng sī kǎo shēng mìng de yì yì hé jià zhí ma huò xǔ nǐ kě yǐ shì shì wèi yú rì běn Qiānyè xiàn Fùjīn shì de rù liàn kā fēi guǎn zhè shì rì běn yī jiā lǎo zì hào bìn zàng gōng sī kāi de kā fēi guǎn wèi xiāo fèi zhě tí gōng tǎng rù guān cái de tǐ yàn fú wù xiāo fèi zhě huā fèi dà yuē liǎng qiān liǎng bǎi rì yuán jiù néng shǐ yòng zhè xiàng fú wù gài shàng guān cái gài sī kǎo rén shēng bìng qiě dǎ kǎ pāi zhào tīng qǐ lái bù tài jí lì dàn shì guān cái shàng yǒu huā huì děng xīn yǐng de shè jì jiǎn shǎo le rén men de dǐ chù qíng xù gāi gōng sī tuī chū cǐ fú wù de mù dì shì ràng gèng duō rén sī kǎo sǐ wáng hé zàng lǐ tóng shí yě hé nián qīng rén men jiàn lì lián xì tàn suǒ xīn de bìn zàng xíng shì zhè yě shì yī gè qì jī kě yǐ ràng rén chóng xīn shěn shì yǔ tā rén de guān xì jìng jìng sī kǎo zài shòu mìng jié shù qián yīng gāi rú hé shēng huó cǐ wài gāi gōng sī yě xī wàng néng tōng guò kā fēi guǎn de huó dòng gǎi biàn nián qīng rén duì bìn zàng yè de kè bǎn yìn xiàng cóng ér zhèn xīng zhěng gè háng yè de fā zhǎn', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"hěn duō:&lt;br /&gt;\r\na lot of \"><ruby><span class=\"si\">很多</span><span class=\"tr\">很多</span><rt>hěn duō</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rén:&lt;br /&gt;\r\npeople, person (HSK1)\"><ruby><span class=\"si\">人</span><span class=\"tr\">人</span><rt>rén</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"huì:&lt;br /&gt;\r\nwould (HSK1)\"><ruby><span class=\"si\">会</span><span class=\"tr\">會</span><rt>huì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎng xiàng:&lt;br /&gt;\r\nimagine (HSK5)\"><ruby><span class=\"si\">想象</span><span class=\"tr\">想像</span><rt>xiǎng xiàng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hūn lǐ:&lt;br /&gt;\r\nwedding (HSK5)\"><ruby><span class=\"si\">婚礼</span><span class=\"tr\">婚禮</span><rt>hūn lǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yàng zi:&lt;br /&gt;\r\nappearance (HSK4)\"><ruby><span class=\"si\">样子</span><span class=\"tr\">樣子</span><rt>yàng zi</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"dàn shì:&lt;br /&gt;\r\nbut (HSK2)\"><ruby><span class=\"si\">但是</span><span class=\"tr\">但是</span><rt>dàn shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn:&lt;br /&gt;\r\nvery (HSK1)\"><ruby><span class=\"si\">很</span><span class=\"tr\">很</span><rt>hěn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shǎo:&lt;br /&gt;\r\nfew (HSK1)\"><ruby><span class=\"si\">少</span><span class=\"tr\">少</span><rt>shǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yǒu:&lt;br /&gt;\r\nhave, there be (HSK1)\"><ruby><span class=\"si\">有</span><span class=\"tr\">有</span><rt>yǒu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rén:&lt;br /&gt;\r\npeople, person (HSK1)\"><ruby><span class=\"si\">人</span><span class=\"tr\">人</span><rt>rén</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"qù:&lt;br /&gt;\r\ngo to (HSK1)\"><ruby><span class=\"si\">去</span><span class=\"tr\">去</span><rt>qù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"sī kǎo:&lt;br /&gt;\r\nthink (HSK5)\"><ruby><span class=\"si\">思考</span><span class=\"tr\">思考</span><rt>sī kǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zàng lǐ:&lt;br /&gt;\r\nfuneral \"><ruby><span class=\"si\">葬礼</span><span class=\"tr\">葬禮</span><rt>zàng lǐ</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎng xiàng:&lt;br /&gt;\r\nimagine (HSK5)\"><ruby><span class=\"si\">想象</span><span class=\"tr\">想像</span><rt>xiǎng xiàng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"guò:&lt;br /&gt;\r\n(the structural particle, used after a verb indicating a past experience action which hasn\'t lasted to the present ) (HSK2)\"><ruby><span class=\"si\">过</span><span class=\"tr\">過</span><rt>guò</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǐ de:&lt;br /&gt;\r\nyour, yours \"><ruby><span class=\"si\">你的</span><span class=\"tr\">你的</span><rt>nǐ de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"sǐ wáng:&lt;br /&gt;\r\ndeath (HSK6)\"><ruby><span class=\"si\">死亡</span><span class=\"tr\">死亡</span><rt>sǐ wáng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hé:&lt;br /&gt;\r\nand, with (HSK1)\"><ruby><span class=\"si\">和</span><span class=\"tr\">和</span><rt>hé</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zàng lǐ:&lt;br /&gt;\r\nfuneral \"><ruby><span class=\"si\">葬礼</span><span class=\"tr\">葬禮</span><rt>zàng lǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ma:&lt;br /&gt;\r\n(aux. question mark) (HSK1)\"><ruby><span class=\"si\">吗</span><span class=\"tr\">嗎</span><rt>ma</rt></ruby></abbr>？<abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎng:&lt;br /&gt;\r\nto want, would like (HSK1)\"><ruby><span class=\"si\">想</span><span class=\"tr\">想</span><rt>xiǎng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"sī kǎo:&lt;br /&gt;\r\nthink (HSK5)\"><ruby><span class=\"si\">思考</span><span class=\"tr\">思考</span><rt>sī kǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shēng mìng:&lt;br /&gt;\r\nlife (HSK4)\"><ruby><span class=\"si\">生命</span><span class=\"tr\">生命</span><rt>shēng mìng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yì yì:&lt;br /&gt;\r\nsignificance (HSK5)\"><ruby><span class=\"si\">意义</span><span class=\"tr\">意義</span><rt>yì yì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hé:&lt;br /&gt;\r\nand, with (HSK1)\"><ruby><span class=\"si\">和</span><span class=\"tr\">和</span><rt>hé</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jià zhí:&lt;br /&gt;\r\nvalue (HSK5)\"><ruby><span class=\"si\">价值</span><span class=\"tr\">價值</span><rt>jià zhí</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ma:&lt;br /&gt;\r\n(aux. question mark) (HSK1)\"><ruby><span class=\"si\">吗</span><span class=\"tr\">嗎</span><rt>ma</rt></ruby></abbr>？<abbr rel=\"tooltip\" title=\"huò xǔ:&lt;br /&gt;\r\nperhaps (HSK6)\"><ruby><span class=\"si\">或许</span><span class=\"tr\">或許</span><rt>huò xǔ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"kě yǐ:&lt;br /&gt;\r\ncan, be able to (HSK2)\"><ruby><span class=\"si\">可以</span><span class=\"tr\">可以</span><rt>kě yǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\ntry (HSK4)\"><ruby><span class=\"si\">试</span><span class=\"tr\">試</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\ntry (HSK4)\"><ruby><span class=\"si\">试</span><span class=\"tr\">試</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wèi yú:&lt;br /&gt;\r\nlie in (HSK6)\"><ruby><span class=\"si\">位于</span><span class=\"tr\">位于</span><rt>wèi yú</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rì běn:&lt;br /&gt;\r\nJapan \"><ruby><span class=\"si\">日本</span><span class=\"tr\">日本</span><rt>rì běn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Qiānyè:&lt;br /&gt;\r\nChiba \"><ruby><span class=\"si\">千叶</span><span class=\"tr\">千葉</span><rt>Qiānyè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiàn:&lt;br /&gt;\r\ncounty (HSK5)\"><ruby><span class=\"si\">县</span><span class=\"tr\">縣</span><rt>xiàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"Fùjīn:&lt;br /&gt;\r\nFuttsu \"><ruby><span class=\"si\">富津</span><span class=\"tr\">富津</span><rt>Fùjīn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\ncity \"><ruby><span class=\"si\">市</span><span class=\"tr\">市</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rù liàn:&lt;br /&gt;\r\nenshrined \"><ruby><span class=\"si\">入殓</span><span class=\"tr\">入殮</span><rt>rù liàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"kā fēi guǎn:&lt;br /&gt;\r\ncafé \"><ruby><span class=\"si\">咖啡馆</span><span class=\"tr\">咖啡館</span><rt>kā fēi guǎn</rt></ruby></abbr>。</p>\r\n<p><abbr rel=\"tooltip\" title=\"zhè:&lt;br /&gt;\r\nthis (HSK1)\"><ruby><span class=\"si\">这</span><span class=\"tr\">這</span><rt>zhè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rì běn:&lt;br /&gt;\r\nJapan \"><ruby><span class=\"si\">日本</span><span class=\"tr\">日本</span><rt>rì běn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī:&lt;br /&gt;\r\none (HSK1)\"><ruby><span class=\"si\">一</span><span class=\"tr\">一</span><rt>yī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jiā:&l