INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(123, 'south-korea-has-the-lowest-fertility-rate-in-the-world', 'South Korea has the lowest fertility rate in the world', '韩国生育率全球最低', 'https://traffic.libsyn.com/secure/learnchinese/5155.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/5155-qvocm3o76kfafbdrpyjfoxvupikfuuuz0qjfstgevm.jpg', '', 'HSK5', 'https://mandarinbean.com/south-korea-has-the-lowest-fertility-rate-in-the-world/', '韩国是世界上生育率最低的国家并且在持续下降一次次地打破惊人的最低纪录年韩国的生育率再下降降至如果要保持人口稳定这个数字应该是如果这种趋势持续下去预计到年韩国人口将减少一半其实全球发达国家的生育率都在下降但是都没有韩国这么严重在未来年韩国符合兵役资格的人口将减少近一半的人口将超过岁这对于经济国家安全都是非常不利的很多政治家认为这已经是国家紧急情况了最近年韩国政府在这个问题上投入了大量的资金但仍然没有效果为什么韩国人尤其是韩国女性不愿意生孩子呢韩国女性受教育程度很高但是却很难找到可以平等分担家务照顾孩子的男人在工作和家庭之间很多人选择了工作社会的压力让人们必须长时间地学习和工作但也因此让女性们没有时间和精力去养育孩子除此之外还有昂贵的房价惊人的教育费用等这些过度而不必要的竞争都是让人们不敢生孩子的原因', 'Hánguó shì shì jiè shàng shēng yù lǜ zuì dī de guó jiā bìng qiě zài chí xù xià jiàng yī cì cì dì dǎ pò jīng rén de zuì dī jì lù nián Hánguó de shēng yù lǜ zài xià jiàng jiàng zhì rú guǒ yào bǎo chí rén kǒu wěn dìng zhè gè shù zì yīng gāi shì rú guǒ zhè zhǒng qū shì chí xù xià qù yù jì dào nián Hánguó rén kǒu jiāng jiǎn shǎo yī bàn qí shí quán qiú fā dá guó jiā de shēng yù lǜ dōu zài xià jiàng dàn shì dōu méi yǒu Hánguó zhè me yán zhòng zài wèi lái nián Hánguó fú hé bīng yì zī gé de rén kǒu jiāng jiǎn shǎo jìn yī bàn de rén kǒu jiāng chāo guò suì zhè duì yú jīng jì guó jiā ān quán dōu shì fēi cháng bù lì de hěn duō zhèng zhì jiā rèn wéi zhè yǐ jīng shì guó jiā jǐn jí qíng kuàng le zuì jìn nián Hánguó zhèng fǔ zài zhè gè wèn tí shàng tóu rù le dà liàng de zī jīn dàn réng rán méi yǒu xiào guǒ wèi shén me Hánguó rén yóu qí shì Hánguó nǚ xìng bù yuàn yì shēng hái zi ne Hánguó nǚ xìng shòu jiào yù chéng dù hěn gāo dàn shì què hěn nán zhǎo dào kě yǐ píng děng fēn dān jiā wù zhào gù hái zi de nán rén zài gōng zuò hé jiā tíng zhī jiān hěn duō rén xuǎn zé le gōng zuò shè huì de yā lì ràng rén men bì xū cháng shí jiān de xué xí hé gōng zuò dàn yě yīn cǐ ràng nǚ xìng men méi yǒu shí jiān hé jīng lì qù yǎng yù hái zi chú cǐ zhī w