INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(128, 'airport-3-boarding', 'Airport (3) – Boarding', '机场 (3) - ', 'https://traffic.libsyn.com/secure/learnchinese/5150.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/5150-qp47xjllqfvj794k75se767f42nr1mkv7t4euf48r6.jpg', '', 'HSK5', 'https://mandarinbean.com/airport-3-boarding/', '工作人员您好大龙你好这是我的护照工作人员您有需要托运的行李吗大龙有在这儿工作人员请您放上来您的行李超重了需要额外支付八十五元大龙付现金可以吗工作人员可以工作人员这是您的护照登机牌和行李超额收据登机口在登机时间是点分往前一直走过安检大龙谢谢机场广播乘坐航班的旅客请注意我们抱歉地通知您由上海飞往西安的航班登机口临时变更请您带好随身物品马上前往登机口谢谢大龙你好请问登机口在哪儿工作人员不在这一层您要先坐电梯到上一层然后乘坐摆渡车到大龙好的谢谢工作人员不客气', 'gōng zuò rén yuán nín hǎo Dàlóng nǐ hǎo zhè shì wǒ de hù zhào gōng zuò rén yuán nín yǒu xū yào tuō yùn de xíng lǐ ma Dàlóng yǒu zài zhè ér gōng zuò rén yuán qǐng nín fàng shàng lái nín de xíng lǐ chāo zhòng le xū yào é wài zhī fù bā shí wǔ yuán Dàlóng fù xiàn jīn kě yǐ ma gōng zuò rén yuán kě yǐ gōng zuò rén yuán zhè shì nín de hù zhào dēng jī pái hé xíng lǐ chāo é shōu jù dēng jī kǒu zài dēng jī shí jiān shì diǎn fēn wǎng qián yī zhí zǒu guò ān jiǎn Dàlóng xièxie jī chǎng guǎng bō chéng zuò háng bān de lǚ kè qǐng zhù yì wǒ men bào qiàn de tōng zhī nín yóu shàng hǎi fēi wǎng xī ān de háng bān dēng jī kǒu lín shí biàn gēng qǐng nín dài hǎo suí shēn wù pǐn mǎ shàng qián wǎng dēng jī kǒu xièxie Dàlóng nǐ hǎo qǐng wèn dēng jī kǒu zài nǎ ér gōng zuò rén yuán bù zài zhè yī céng nín yào xiān zuò diàn tī dào shàng yī céng rán hòu chéng zuò bǎi dù chē dào Dàlóng hǎo de xièxie gōng zuò rén yuán bù kè qì', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"gōng zuò:&lt;br /&gt;\r\nWork (HSK1)\"><ruby><span class=\"si\">工作</span><span class=\"tr\">工作</span><rt>gōng zuò</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rén yuán:&lt;br /&gt;\r\nstaff (HSK5)\"><ruby><span class=\"si\">人员</span><span class=\"tr\">人員</spa