INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(131, 'go-to-the-supermarket-or-the-market', 'Go to the supermarket or the market?', '去超市还是去市场？', 'https://traffic.libsyn.com/secure/learnchinese/5147.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/5147-qkexbc1c37bc2mvzd4aqh2cl01xx3m4tzw8xt8w4so.jpg', '', 'HSK5', 'https://mandarinbean.com/go-to-the-supermarket-or-the-market/', '大龙小咪你怎么一边吃饭一边看手机吴小咪我在看短信好多商场给我发消息最近很多东西打折大龙是吗我也想买点儿吴小咪你想买什么大龙我想买台新电脑如果还有别的东西打折我也买一些吴小咪你可以去商场或者电脑城现在很多牌子比如苹果或者联想等等商场里面都有体验店你可以亲自去看看要是你想自己组装电脑的话你就去电脑城除了商场和电脑城你还可以网购大龙我的银行卡还没有办好不能网购而且我不会用中国的网购软件吴小咪没关系下次我教你网购大龙谢谢你要是我想买衣服去哪儿呢吴小咪要是买衣服的话大商场商店和服装市场都挺不错的大龙听说服装市场的衣服很便宜吴小咪对但是商场的衣服质量更好要是你想找一些比较新颖的款式有些小服装店也挺好的大龙你平时在哪买蔬菜和水果呢吴小咪我喜欢去超市又近又方便超市里很多菜已经洗好切好了可以节约时间不过超市里的菜没有菜市场便宜大龙我家附近好像没有菜市场吴小咪有的就在你住的那条街后面大龙外面是不是有个蓝色的大牌子原来那是菜市场啊难怪我有一次早上跑步的时候看见那边有很多人吴小咪是啊如果你想买既新鲜又便宜的菜可以去那个菜市场那里的老板既热心又善良你可以请他们帮你处理鱼或者别的肉对了旁边还有一个花卉市场呢大龙花卉市场是卖花的吗我从来没听过吴小咪不仅卖花而且也卖一些别的植物大龙听起来很有意思除了花卉市场还有别的什么市场吗吴小咪还有很多比如农贸市场可以买农作物的种子建材市场可以买装修房子的材料古玩市场可以买一些古董大龙下次我想去古玩市场逛一逛', 'Dàlóng Xiǎomī nǐ zěn me yī biān chī fàn yī biān kàn shǒu jī Wú Xiǎomī wǒ zài kàn duǎn xìn hǎo duō shāng chǎng gěi wǒ fā xiāo xī zuì jìn hěn duō dōng xī dǎ zhé Dàlóng shì ma wǒ yě xiǎng mǎi diǎn ér Wú Xiǎomī nǐ xiǎng mǎi shén me Dàlóng wǒ xiǎng mǎi tái xīn diàn nǎo rú guǒ hái yǒu bié de dōng xī dǎ zhé wǒ yě mǎi yī xiē Wú Xiǎomī nǐ kě yǐ qù shāng chǎng huò zhě diàn nǎo chéng xiàn zài hěn duō pái zi bǐ rú píng guǒ huò zhě lián xiǎng děng děng shāng chǎng lǐ miàn dōu yǒu tǐ yàn diàn nǐ kě yǐ qīn zì qù kàn kàn yào shì nǐ xiǎng zì jǐ zǔ zhuāng diàn nǎo de huà nǐ jiù qù diàn nǎo chéng chú le shāng chǎng hé diàn nǎo chéng nǐ hái kě yǐ wǎng gòu Dàlóng wǒ de yín háng kǎ hái méi yǒu bàn hǎo bù néng wǎng gòu ér qiě wǒ bù huì yòng zhōng guó de wǎng gòu ruǎn jiàn Wú Xiǎomī méi guān xì xià cì wǒ jiāo nǐ wǎng gòu Dàlóng xiè xiè nǐ yào shì wǒ xiǎng mǎi yī fú qù nǎ ér ne Wú Xiǎomī yào shì mǎi yī fú de huà dà shāng chǎng shāng diàn hé fú zhuāng shì chǎng dōu tǐng bù cuò de Dàlóng tīng shuō fú zhuāng shì chǎng de yī fú hěn piányi Wú Xiǎomī duì dàn shì shāng chǎng de yī fú zhì liàng gèng hǎo yào shì nǐ xiǎng zhǎo yī xiē bǐ jiào xīn yǐng de kuǎn shì yǒu xiē xiǎo fú zhuāng diàn yě tǐng hǎo de Dàlóng nǐ píng shí zài nǎ mǎi shū cài hé shuǐ guǒ ne Wú Xiǎomī wǒ xǐ huān qù chāo shì yòu jìn yòu fāng biàn chāo shì lǐ hěn duō cài yǐ jīng xǐ hǎo qiē hǎo le kě yǐ jié yuē shí jiān bù guò chāo shì lǐ de cài méi yǒu cài shì chǎng piányi Dàlóng wǒ jiā fù jìn hǎo xiàng méi yǒu cài shì chǎng Wú Xiǎomī yǒu de jiù zài nǐ zhù de nà tiáo jiē hòu miàn Dàlóng wài miàn shì bù shì yǒu gè lán sè de dà pái zi yuán lái nà shì cài shì chǎng a nán guài wǒ yǒu yī cì zǎo shàng pǎo bù de shí hòu kàn jiàn nà biān yǒu hěn duō rén Wú Xiǎomī shì a rú guǒ nǐ xiǎng mǎi jì xīn xiān yòu piányi de cài kě yǐ qù nà gè cài shì chǎng nà lǐ de lǎo bǎn jì rè xīn yòu shàn liáng nǐ kě yǐ qǐng tā men bāng nǐ chǔ lǐ yú huò zhě bié de ròu duì le páng biān hái yǒu yī gè huā huì shì chǎng ne Dàlóng huā huì shì chǎng shì mài huā de ma wǒ cóng lái méi tīng guò Wú Xiǎomī bù jǐn mài huā ér qiě yě mài yī xiē bié de zhí wù Dàlóng tīng qǐ lái hěn yǒu yìsi chú le huā huì shì chǎng hái yǒu bié de shén me shì chǎng ma Wú Xiǎomī hái yǒu hěn duō bǐ rú nóng mào shì chǎng kě yǐ mǎi nóng zuò wù de zhǒng zi jiàn cái shì chǎng kě yǐ mǎi zhuāng xiū fáng zi de cái liào gǔ wán shì chǎng kě yǐ mǎi yī xiē gǔ dǒng Dàlóng xià cì wǒ xiǎng qù gǔ wán shì chǎng guàng yī guàng', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"Dàlóng:&lt;br /&gt;\r\nDalong\"><ruby><span class=\"si\">大龙</span><span class=\"tr\">大龍</span><rt>Dàlóng</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"Xiǎomī:&lt;br /&gt;\r\nXiaomi\"><ruby><span class=\"si\">小咪</span><span class=\"tr\">小咪</span><rt>Xiǎomī</rt></ruby></abbr>！<abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zěn me:&lt;br /&gt;\r\nwhy (HSK1)\"><ruby><span class=\"si\">怎么</span><span class=\"tr\">怎麽</span><rt>zěn me</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī biān:&lt;br /&gt;\r\n一边……一边…… two actions going on at the same time (HSK3)\"><ruby><span class=\"si\">一边</span><span class=\"tr\">一邊</span><rt>yī biān</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"chī:&lt;br /&gt;\r\neat (HSK1)\"><ruby><span class=\"si\">吃</span><span class=\"tr\">吃</span><rt>chī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"fàn:&lt;br /&gt;\r\nmeal\"><ruby><span class=\"si\">饭</span><span class=\"tr\">飯</span><rt>fàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī biān:&lt;br /&gt;\r\n一边……一边…… two actions going on at the same time (HSK3)\"><ruby><span class=\"si\">一边</span><span class=\"tr\">一邊</span><rt>yī biān</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"kàn:&lt;br /&gt;\r\nlook (HSK1)\"><ruby><span class=\"si\">看</span><span class=\"tr\">看</span><rt>kàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shǒu jī:&lt;br /&gt;\r\ncell phone (HSK2)\"><ruby><span class=\"si\">手机</span><span class=\"tr\">手機</span><rt>shǒu jī</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎomī:&lt;br /&gt;\r\nWu Xiaomi\"><ruby><span class=\"si\">吴小咪</span><span class=\"tr\">吳小咪</span><rt>Wú Xiǎomī</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zài:&lt;br /&gt;\r\n(located) at / (to be) in (HSK1)\"><ruby><span class=\"si\">在</span><span class=\"tr\">在</span><rt>zài</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"kàn:&lt;br /&gt;\r\nlook (HSK1)\"><ruby><span class=\"si\">看</span><span class=\"tr\">看</span><rt>kàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"duǎn xìn:&lt;br /&gt;\r\nmessage (HSK5)\"><ruby><span class=\"si\">短信</span><span class=\"tr\">短信</span><rt>duǎn xìn</rt></ruby></abbr>。<abbr rel=\"tooltip\" title=\"hǎo:&lt;br /&gt;\r\nquite (HSK1)\"><ruby><span class=\"si\">好</span><span class=\"tr\">好</span><rt>hǎo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"duō:&lt;br /&gt;\r\nmany, more (HSK1)\"><ruby><span class=\"si\">多</span><span class=\"tr\">多</span><rt>duō</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shāng chǎng:&lt;br /&gt;\r\nshopping mall\"><ruby><span class=\"si\">商场</span><span class=\"tr\">商場</span><rt>shāng chǎng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gěi:&lt;br /&gt;\r\nto, for (HSK2)\"><ruby><span class=\"si\">给</span><span class=\"tr\">給</span><rt>gěi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"fā:&lt;br /&gt;\r\nsend (HSK4)\"><ruby><span class=\"si\">发</span><span class=\"tr\">發</span><rt>fā</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiāo xī:&lt;br /&gt;\r\ninformation (HSK4)\"><ruby><span class=\"si\">消息</span><span class=\"tr\">消息</span><rt>xiāo xī</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"zuì jìn:&lt;br /&gt;\r\nrecently (HSK3)\"><ruby><span class=\"si\">最近</span><span class=\"tr\">最近</span><rt>zuì jìn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hěn duō:&lt;br /&gt;\r\na lot of\"><ruby><span class=\"si\">很多</span><span class=\"tr\">很多</span><rt>hěn duō</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dōng xī:&lt;br /&gt;\r\nthing, stuff (HSK1)\"><ruby><span class=\"si\">东西</span><span class=\"tr\">東西</span><rt>dōng xī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dǎ zhé:&lt;br /&gt;\r\nDiscount (HSK4)\"><ruby><span class=\"si\">打折</span><span class=\"tr\">打折</span><rt>dǎ zhé</rt></ruby></abbr>。</p>\r\n<p><abbr rel=\"tooltip\" title=\"Dàlóng:&lt;br /&gt;\r\nDalong\"><ruby><span class=\"si\">大龙</span><span class=\"tr\">大龍</span><rt>Dàlóng</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nbe (HSK1)\"><ruby><span class=\"si\">是</span><span class=\"tr\">是</span><rt>shì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ma:&lt;br /&gt;\r\n(aux. question mark) (HSK1)\"><ruby><span class=\"si\">吗</span><span class=\"tr\">嗎</span><rt>ma</rt></ruby></abbr>？<abbr rel=\"tooltip\" title=\"wǒ:&lt;br /&gt;\r\nI, me (HSK1)\"><ruby><span class=\"si\">我</span><span class=\"tr\">我</span><rt>wǒ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yě:&lt;br /&gt;\r\nalso (HSK2)\"><ruby><span class=\"si\">也</span><span class=\"tr\">也</span><rt>yě</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎng:&lt;br /&gt;\r\nto want, would like (HSK1)\"><ruby><span class=\"si\">想</span><span class=\"tr\">想</span><rt>xiǎng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"mǎi:&lt;br /&gt;\r\npurchase (HSK1)\"><ruby><span class=\"si\">买</span><span class=\"tr\">買</span><rt>mǎi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"diǎn ér:&lt;br /&gt;\r\nA little bit\"><ruby><span class=\"si\">点儿</span><span class=\"tr\">點兒</span><rt>diǎn ér</rt></ruby></abbr>。</p>\r\n<p><abbr rel=\"tooltip\" title=\"Wú Xiǎomī:&lt;br /&gt;\r\nWu Xiaomi\"><ruby><span class=\"si\">吴小咪</span><span class=\"tr\">吳小咪</span><rt>Wú Xiǎomī</rt></ruby></abbr>：<abbr rel=\"tooltip\" title=\"nǐ:&lt;br /&gt;\r\nyou (HSK1)\"><ruby><span class=\"si\">你</span><span class=\"tr\">你</span><rt>nǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎng:&lt;br /&gt;\r\nto want, would like (HSK1)\"><ruby><span class=\"si\">想</span><span class=\"tr\">想</span><rt>xiǎng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"mǎi:&lt;br /&gt;\r\npurchase (HSK1)\"><ruby><span class=\"si\">买</span><span class=\"tr\">買</span><rt>mǎi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shén me:&lt;br /&gt;\r\nWhat (HSK1)\"><ruby><span class=\"si\">什么</span><span class=\"tr\">什麽</span><rt>shén me</rt></ruby></abbr>？</p>\r\n<p><abbr rel=\"tooltip\" title=\"Dàlóng:&lt;br /&gt;\r\nDalong\"><ruby><span class=\"si