INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(138, 'office-workers-who-are-afraid-of-physical-examination', 'Office workers who are afraid of physical examination', '害怕体检的职场人', 'https://traffic.libsyn.com/secure/learnchinese/5140.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/5140-qa5x7a5laf5wd9teawuxoqy12152eqwzesxmgse4wi.jpg', '', 'HSK5', 'https://mandarinbean.com/office-workers-who-are-afraid-of-physical-examination/', '每到岁末年初大家就会开始除旧迎新为新的一年制定计划立下新的很多人都希望自己能早睡早起注意身体今年也不例外但是调查显示超过四成的职场人表示没有定时体检的习惯从年龄看职场人中至少两年没有体检的人达到了三成的后已经超过五年以上没有体检过后和后分别只有和的人定时体检从性别看女性会定时体检的比例为男性则为相差了将近十个百分点在体检这件事上男性应该向女性多学习从职业看不同职业的体检习惯差异也很大过去一年中九成的国企银行事业单位员工参加过体检政府公务员的体检比例也达到了八成但是在互联网从业者中超过五成的人已经一年以上没有参加体检了而人们通常认为时间更灵活的自由职业者们在超过五年没体检过的人中占比达到了事实上不按时体检的原因中大家提到最多的是没感觉不舒服害怕体检舍不得花钱的互联网从业者都因为害怕而选择了不参加体检一方面高达九成的人都明白不可以讳疾忌医有问题就应该早发现早治疗的道理另一方面他们又都不行动职场人不体检除了以上原因体检机构的体验差也是一大影响因素比如每次体检都需要排队很长时间担心隐私问题检查时的紧张和疼痛等因为生理差异女性体检时的不适感通常比男性更多最后还是需要提醒大家想拥有健康的身体需要长期坚持平时注意按时体检是不能逃避的不论你是什么年龄职业性别希望你新的一年身体健康努力实现自己的新年计划吧', 'měi dào suì mò nián chū dà jiā jiù huì kāi shǐ chú jiù yíng xīn wèi xīn de yī nián zhì dìng jì huà lì xià xīn de hěn duō rén dōu xī wàng zì jǐ néng zǎo shuì zǎo qǐ zhù yì shēn tǐ jīn nián yě bù lì wài dàn shì diào chá xiǎn shì chāo guò sì chéng de zhí chǎng rén biǎo shì méi yǒu dìng shí tǐ jiǎn de xí guàn cóng nián líng kàn zhí chǎng rén zhōng zhì shǎo liǎng nián méi yǒu tǐ jiǎn de rén dá dào le sān chéng de hòu yǐ jīng chāo guò wǔ nián yǐ shàng méi yǒu tǐ jiǎn guò hòu hé hòu fēn bié zhǐ yǒu hé de rén dìng shí tǐ jiǎn cóng xìng bié kàn nǚ xìng huì dìng shí tǐ jiǎn de bǐ lì wéi nán xìng zé wéi xiāng chā le jiāng jìn shí gè bǎi fēn diǎn zài tǐ jiǎn zhè jiàn shì shàng nán xìng yīng gāi xiàng nǚ xìng duō xué xí cóng zhí yè kàn bù tóng zhí yè de tǐ jiǎn xí guàn chā yì yě hěn dà guò qù yī nián zhōng jiǔ chéng de guó qǐ yín háng shì yè dān wèi yuán gōng cān jiā guò tǐ jiǎn zhèng fǔ gōng wù yuán de tǐ jiǎn bǐ lì yě dá dào le bā chéng dàn shì zài hù lián wǎng cóng yè zhě zhōng chāo guò wǔ chéng de rén yǐ jīng yī nián yǐ shàng méi yǒu cān jiā tǐ jiǎn le ér rén men tōng cháng rèn wéi shí jiān gèng líng huó de zì yóu zhí yè zhě men zài chāo guò wǔ nián méi tǐ jiǎn guò de rén zhōng zhàn bǐ dá dào le shì shí shàng bù àn shí tǐ jiǎn de yuán yīn zhōng dà jiā tí dào zuì duō de shì méi gǎn jué bù shū fú hài pà tǐ jiǎn shě bù dé huā qián de hù lián wǎng cóng yè zhě dōu yīn wèi hài pà ér xuǎn zé le bù cān jiā tǐ jiǎn yī fāng miàn gāo dá jiǔ chéng de rén dōu míng bái bù kě yǐ huì jí jì yī yǒu wèn tí jiù yīng gāi zǎo fā xiàn zǎo zhì liáo de dào lǐ lìng yī fāng miàn tā men yòu dōu bù xíng dòng zhí chǎng rén bù tǐ jiǎn chú le yǐ shàng yuán yīn tǐ jiǎn jī gòu de tǐ yàn chà yě shì yī dà yǐng xiǎng yīn sù bǐ rú měi cì tǐ jiǎn dōu xū yào pái duì hěn cháng shí jiān dān xīn yǐn sī wèn tí jiǎn chá shí de jǐn zhāng hé téng tòng děng yīn wèi shēng lǐ chā yì nǚ xìng tǐ jiǎn shí de bù shì gǎn tōng cháng bǐ nán xìng gèng duō zuì hòu hái shì xū yào tí xǐng dà jiā xiǎng yōng yǒu jiàn kāng de shēn tǐ xū yào cháng qī jiān chí píng shí zhù yì àn shí tǐ jiǎn shì bù néng táo bì de bù lùn nǐ shì shén me nián líng zhí yè xìng bié xī wàng nǐ xīn de yī nián shēn tǐ jiàn kāng nǔ lì shí xiàn zì jǐ de xīn nián jì huà ba', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"měi:&lt;br /&gt;\r\nEvery (HSK2)\"><ruby><span class=\"si\">每</span><span class=\"tr\">每</span><rt>měi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dào:&lt;br /&gt;\r\nto arrive,to reach (HSK2)\"><ruby><span class=\"si\">到</span><span class=\"tr\">到</span><rt>dào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"suì:&lt;br /&gt;\r\nage (HSK1)\"><ruby><span class=\"si\">岁</span><span class=\"tr\">歲</span><rt>suì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"mò:&lt;br /&gt;\r\nthe end\"><ruby><span class=\"si\">末</span><span cl