INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(148, 'qingming-festival-2', 'Qingming Festival', '清明节', 'https://traffic.libsyn.com/secure/learnchinese/6139.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/6139-r43vzyuoec0oj0gok5wzadz33hpemnhajzvfh0b74k.jpg', '', 'HSK6', 'https://mandarinbean.com/qingming-festival-2/', '春天到了很多人都会想起唐朝诗人杜牧写的关于清明的那首诗清明时节雨纷纷路上行人欲断魂不过最早的清明并不是一个纪念节日只是天气变化的一个名字这时候中国大部分地方天气变暖花草树木开始生长正是农民种地的好时候老话说清明连着谷雨播种插秧要抓紧后来清明怎么变成纪念祖先的节日呢这和一个叫寒食节的旧节日有关古代人为了纪念一位叫介子推的忠臣规定春天三天不能生火做饭因为很久以前人们用木头取火很不容易春天正好要换新火种到了汉朝寒食节这天白天不许点火晚上皇宫才会把新火传给大臣们不能做饭的日子人们要提前准备冷食北方人会做燕子形状的面饼南方人做青色的糯米团子人们还习惯在这段时间打扫祖先的墓地古代人很重视纪念祖先后来慢慢形成了扫墓的传统到了唐朝大家常在清明前后扫墓政府专门放假让百姓做这件事后来清明变得越来越重要连寒食节吃东西踢球荡秋千这些活动都变成了清明的习俗清明还吸收了另一个叫上巳节的节日内容上巳节在三月三日人们会去河边洗澡春游唐朝开始扫墓的人会顺便在野外游玩清明又有了踏青节的名字现在的清明节主要有三个内容扫墓纪念祖先野外春游种树保护自然就像古代画家张择端画的清明上河图那样这个节日既有对过去的怀念也有春天的欢乐人们通过这个节日表达对家人的思念也享受美好的春光', 'chūn tiān dào le hěn duō rén dōu huì xiǎng qǐ Táng cháo shī rén Dù Mù xiě de guān yú Qīngmíng de nà shǒu shī Qīngmíng shí jié yǔ fēn fēn lù shàng xíng rén yù duàn hún bù guò zuì zǎo de Qīngmíng bìng bù shì yī gè jì niàn jié rì zhǐ shì tiān qì biàn huà de yī gè míng zì zhè shí hòu Zhōng guó dà bù fèn dì fāng tiān qì biàn nuǎn huā cǎo shù mù kāi shǐ shēng zhǎng zhèng shì nóng mín zhòng dì de hǎo shí hòu lǎo huà shuō Qīngmíng lián zhe gǔ yǔ bō zhòng chā yāng yào zhuā jǐn hòu lái Qīngmíng zěn me biàn chéng jì niàn zǔ xiān de jié rì ne zhè hé yī gè jiào Hánshí jié de jiù jié rì yǒu guān gǔ dài rén wèi le jì niàn yī wèi jiào Jiè Zǐtuī de zhōng chén guī dìng chūn tiān sān tiān bù néng shēng huǒ zuò fàn yīn wèi hěn jiǔ yǐ qián rén men yòng mù tou qǔ huǒ hěn bù róng yì chūn tiān zhèng hǎo yào huàn xīn huǒ zhǒng dào le Hàn cháo Hánshí jié zhè tiān bái tiān bù xǔ diǎn huǒ wǎn shàng huáng gōng cái huì bǎ xīn huǒ chuán gěi dà chén men bù néng zuò fàn de rì zi rén men yào tí qián zhǔn bèi lěng shí běi fāng rén huì zuò yàn zi xíng zhuàng de miàn bǐng nán fāng rén zuò qīng sè de nuò mǐ tuán zi rén men hái xí guàn zài zhè duàn shí jiān dǎ sǎo zǔ xiān de mù dì gǔ dài rén hěn zhòng shì jì niàn zǔ xiān hòu lái màn màn xíng chéng le sǎo mù de chuán tǒng dào le táng cháo dà jiā cháng zài Qīngmíng qián hòu sǎo mù zhèng fǔ zhuān mén fàng jià ràng bǎi xìng zuò zhè jiàn shì hòu lái Qīngmíng biàn de yuè lái yuè zhòng yào lián Hánshí jié chī dōng xī tī qiú dàng qiū qiān zhè xiē huó dòng dōu biàn chéng le Qīngmíng de xí sú Qīngmíng hái xī shōu le lìng yī gè jiào Shàngsì jié de jié rì nèi róng Shàngsì jié zài sān yuè sān rì rén men huì qù hé biān xǐ zǎo chūn yóu Táng cháo kāi shǐ sǎo mù de rén huì shùn biàn zài yě wài yóu wán Qīngmíng yòu yǒu le Tàqīng jié de míng zì xiàn zài de Qīngmíng jié zhǔ yào yǒu sān gè nèi róng sǎo mù jì niàn zǔ xiān yě wài chūn yóu zhòng shù bǎo hù zì rán jiù xiàng gǔ dài huà jiā zhāng zé duān huà de Qīngmíng shàng hé tú nà yàng zhè gè jié rì jì yǒu duì guò qù de huái niàn yě yǒu chūn tiān de huān lè rén men tōng guò zhè gè jié rì biǎo dá duì jiā rén de sī niàn yě xiǎng shòu měi hǎo de chūn guāng', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"chūn tiān:&lt;br /&gt;\r\nspring \"><ruby><span class=\"si\">春天</span><span class=\"tr\">春天</span><rt>chūn tiān</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dào:&lt;br /&gt;\r\nto arrive,to reach (HSK2)\"><ruby><span class=\"si\">到</span><span class=\"tr\">到</span><rt>dào</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr>， <abbr rel=\"tooltip\" title=\"hěn duō:&lt;br /&gt;\r\na lot of \"><ruby><span class=\"si\">很多</span><span class=\"tr\">很多</span><rt>hěn duō</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rén:&lt;br /&gt;\r\npeople, person (HSK1)\"><ruby><span class=\"si\">人</span><span class=\"tr\">人</span><rt>rén</