INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(153, 'chinas-144-hour-transit-visa-exemption', 'China’s 144-hour transit visa exemption', '中国144小时过境免签', 'https://traffic.libsyn.com/secure/learnchinese/6133.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/6133-qxc3niafnie8w989npcowvqi3vg76lzt0b7exk8pqq.jpg', '', 'HSK6', 'https://mandarinbean.com/chinas-144-hour-transit-visa-exemption/', '年以来中国先后对法国德国澳大利亚等个国家试行单方面免签政策新增与新加坡泰国等个国家互免签证自去年月以来位于个省市的个对外开放口岸已对个国家人员实施了至小时免签政策据国家移民管理局数据年上半年通过免签入境中国的外国人总计万人次同比增长倍小时免签属于中间型政策具有免签的色彩但又有限制能够对已有的免签政策进行补充主要服务于中转型游客以增加他们在停留时间内旅游认识中国的可能性过境免签有效有四个条件有效期内的护照飞往第三方国家或地区的机票不能在中国境内转机填好入境卡务必遵守停留范围的规定因为中国太大了尤其对于初次来华的外国游客大多数人对中国的地理认知极其有限甚至不清楚景点的分布状况分不清许多城市因而在理解小时政策的设计时也感到吃力一些国际游客可能会因为理解不全面由于出入境城市超出活动区域范围被滞留机场从而产生失望情绪和不满意所以在出发之前要了解清楚免签政策的具体要求旅游时也可能会有很多文化碰撞和不适应虽然这也是旅游的奇妙之处但当下有很多问题需要被解决比如如果没有任何本地朋友的接待如何能让选择自由行的外国游客在一天内快速学会二维码支付中国的使用等问题不过这些问题也正在被积极地讨论和解决相信很快就会有更便利的旅游条件中国开放了免签意味着为更多人提供了环游中国的机会能够体验文化与当地人交流享受食物外国游客对中国最高的评价依次有安全互联网便利环境干净人民很友好性价比很高等这个政策有助于消除很多人的偏见', 'nián yǐ lái Zhōngguó xiān hòu duì Fǎguó Déguó àodàlìyà děng gè guó jiā shì xíng dān fāng miàn miǎn qiān zhèng cè xīn zēng yǔ Xīnjiāpō tàiguó děng gè guó jiā hù miǎn qiān zhèng zì qù nián yuè yǐ lái wèi yú gè shěng shì de gè duì wài kāi fàng kǒu àn yǐ duì gè guó jiā rén yuán shí shī le zhì xiǎo shí miǎn qiān zhèng cè jù guó jiā yí mín guǎn lǐ jú shù jù nián shàng bàn nián tōng guò miǎn qiān rù jìng Zhōngguó de wài guó rén zǒng jì wàn rén cì tóng bǐ zēng zhǎng bèi xiǎo shí miǎn qiān shǔ yú zhōng jiān xíng zhèng cè jù yǒu miǎn qiān de sè cǎi dàn yòu yǒu xiàn zhì néng gòu duì yǐ yǒu de miǎn qiān zhèng cè jìn xíng bǔ chōng zhǔ yào fú wù yú zhōng zhuǎn xíng yóu kè yǐ zēng jiā tā men zài tíng liú shí jiān nèi lǚ yóu rèn shí Zhōngguó de kě néng xìng guò jìng miǎn qiān yǒu xiào yǒu sì gè tiáo jiàn yǒu xiào qī nèi de hù zhào fēi wǎng dì sān fāng guó jiā huò dì qū de jī piào bù néng zài Zhōngguó jìng nèi zhuǎn jī tián hǎo rù jìng kǎ wù bì zūn shǒu tíng liú fàn wéi de guī dìng yīn wèi Zhōngguó tài dà le yóu qí duì yú chū cì lái huá de wài guó yóu kè dà duō shù rén duì Zhōngguó de dì lǐ rèn zhī jí qí yǒu xiàn shèn zhì bù qīng chǔ jǐng diǎn de fēn bù zhuàng kuàng fēn bù qīng xǔ duō chéng shì yīn ér zài lǐ jiě xiǎo shí zhèng cè de shè jì shí yě gǎn dào chī lì yī xiē guó jì yóu kè kě néng huì yīn wèi lǐ jiě bù quán miàn yóu yú chū rù jìng chéng shì chāo chū huó dòng qū yù fàn wéi bèi zhì liú jī chǎng cóng ér chǎn shēng shī wàng qíng xù hé bù mǎn yì suǒ yǐ zài chū fā zhī qián yào liǎo jiě qīng chǔ miǎn qiān zhèng cè de jù tǐ yāo qiú lǚ yóu shí yě kě néng huì yǒu hěn duō wén huà pèng zhuàng hé bù shì yìng suī rán zhè yě shì lǚ yóu de qí miào zhī chù dàn dāng xià yǒu hěn duō wèn tí xū yào bèi jiě jué bǐ rú rú guǒ méi yǒu rèn hé běn dì péng yǒu de jiē dài rú hé néng ràng xuǎn zé zì yóu xíng de wài guó yóu kè zài yī tiān nèi kuài sù xué huì èr wéi mǎ zhī fù Zhōngguó de shǐ yòng děng wèn tí bù guò zhè xiē wèn tí yě zhèng zài bèi jī jí de tǎo lùn hé jiě jué xiāng xìn hěn kuài jiù huì yǒu gèng biàn lì de lǚ yóu tiáo jiàn Zhōngguó kāi fàng le miǎn qiān yì wèi zhe wéi gèng duō rén tí gōng le huán yóu Zhōngguó de jī huì néng gòu tǐ yàn wén huà yǔ dāng dì rén jiāo liú xiǎng shòu shí wù wài guó yóu kè duì Zhōngguó zuì gāo de píng jià yī cì yǒu ān quán hù lián wǎng biàn lì huán jìng gān jìng rén mín hěn yǒu hǎo xìng jià bǐ hěn gāo děng zhè gè zhèng cè yǒu zhù yú xiāo chú hěn duō rén de piān jiàn', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p>2023<abbr rel=\"tooltip\" title=\"nián:&lt;br /&gt;\r\nYear (HSK1)\"><ruby><span class=\"si\">年</span><span class=\"tr\">年</span><rt>nián</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yǐ lái:&lt;br /&gt;\r\nsince (HSK5)\"><ruby><span class=\"si\">以来</span><span class=\"tr\">以來</span><rt>yǐ lái</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"Zhōngguó:&l