INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(157, 'social-media-and-depression', 'Social media and depression', '社交媒体与抑郁症的关系', 'https://traffic.libsyn.com/secure/learnchinese/6129.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/6129-qrwlyvyxcya6qputdet4t1il0vzc12rwpgy3n8mmcq.jpg', '', 'HSK6', 'https://mandarinbean.com/social-media-and-depression/', '社交媒体是否让孩子们变得不幸福越来越多的研究表明使用社交媒体与抑郁之间存在某种关联研究显示经常使用等平台的青少年患抑郁症的比例高于那些不常使用的孩子从年到年青少年的抑郁症状增加了女生的自杀率上升了这段时间智能手机的普及使得青少年更多地通过社交媒体进行互动减少了面对面的交流专家认为社交媒体上的人际关系无法提供足够的情感价值浅层次的关系容易导致孤独感和漂泊感虽然有些孤独的青少年通过社交媒体找到情感支持但整体来看社交媒体对大多数人的心理健康影响较为负面此外使用社交媒体还可能导致自我评价下降注意力分散缺乏锻炼和睡眠不足等问题这些因素共同作用进一步加剧了青少年的心理健康问题家长可以通过定期检查孩子的手机使用情况平衡线上和线下的社交活动限制睡前使用手机等措施来减少社交媒体的负面影响关注孩子的行为和情绪变化必要时寻求心理医生的帮助以确保孩子的心理健康', 'shè jiāo méi tǐ shì fǒu ràng hái zi men biàn de bù xìng fú yuè lái yuè duō de yán jiū biǎo míng shǐ yòng shè jiāo méi tǐ yǔ yì yù zhī jiān cún zài mǒu zhǒng guān lián yán jiū xiǎn shì jīng cháng shǐ yòng děng píng tái de qīng shào nián huàn yì yù zhèng de bǐ lì gāo yú nà xiē bù cháng shǐ yòng de hái zi cóng nián dào nián qīng shào nián de yì yù zhèng zhuàng zēng jiā le nǚ shēng de zì shā lǜ shàng shēng le zhè duàn shí jiān zhì néng shǒu jī de pǔ jí shǐ de qīng shào nián gèng duō de tōng guò shè jiāo méi tǐ jìn xíng hù dòng jiǎn shǎo le miàn duì miàn de jiāo liú zhuān jiā rèn wéi shè jiāo méi tǐ shàng de rén jì guān xì wú fǎ tí gōng zú gòu de qíng gǎn jià zhí qiǎn céng cì de guān xì róng yì dǎo zhì gū dú gǎn hé piāo bó gǎn suī rán yǒu xiē gū dú de qīng shào nián tōng guò shè jiāo méi tǐ zhǎo dào qíng gǎn zhī chí dàn zhěng tǐ lái kàn shè jiāo méi tǐ duì dà duō shù rén de xīn lǐ jiàn kāng yǐng xiǎng jiào wéi fù miàn cǐ wài shǐ yòng shè jiāo méi tǐ hái kě néng dǎo zhì zì wǒ píng jià xià jiàng zhù yì lì fēn sàn quē fá duàn liàn hé shuì mián bù zú děng wèn tí zhè xiē yīn sù gòng tóng zuò yòng jìn yī bù jiā jù le qīng shào nián de xīn lǐ jiàn kāng wèn tí jiā zhǎng kě yǐ tōng guò dìng qī jiǎn chá hái zi de shǒu jī shǐ yòng qíng kuàng píng héng xiàn shàng hé xiàn xià de shè jiāo huó dòng xiàn zhì shuì qián shǐ yòng shǒu jī děng cuò shī lái jiǎn shǎo shè jiāo méi tǐ de fù miàn yǐng xiǎng guān zhù hái zi de xíng wéi hé qíng xù biàn huà bì yào shí xún qiú xīn lǐ yī shēng de bāng zhù yǐ què bǎo hái zi de xīn lǐ jiàn kāng', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"shè jiāo:&lt;br /&gt;\r\nsocial contact \"><ruby><span class=\"si\">社交</span><span class=\"tr\">社交</span><rt>shè jiāo</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"méi tǐ:&lt;br /&gt;\r\nmedia (HSK6)\"><ruby><span class=\"si\">媒体</span><span class=\"tr\">媒體</span><rt>méi tǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì fǒu:&lt;br /&gt;\r\nwhether or not (HSK5)\"><ruby><span class=\"si\">是否</span><span class=\"tr\">是否</span><rt>shì fǒu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"ràng:&lt;br /&gt;\r\nlet (HSK2)\"><ruby><span class=\"si\">让</span><span class=\"tr\">讓</span><rt>ràng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hái zi:&lt;br /&gt;\r\nchild (HSK2)\"><ruby><span class=\"si\">孩子</span><span class=\"tr\">孩子</span><rt>hái zi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"men:&lt;br /&gt;\r\n(aux. plural) \"><ruby><span class=\"si\">们</span><span class=\"tr\">們</span><rt>men</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"biàn:&lt;br /&gt;\r\nbecome, change \"><ruby><span class=\"si\">变</span><span class=\"tr\">變</span><rt>biàn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux.) (HSK2)\"><ruby><span class=\"si\">得</span><span class=\"tr\">得</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bù:&lt;br /&gt;\r\nno, not (HSK1)\"><ruby><span class=\"si\">不</span><span class=\"tr\">不</span><rt>bù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xìng fú:&lt;br /&gt;\r\nhappiness (HSK4)\"><ruby>