INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(158, 'childrens-growth-companion', 'Children’s growth companion', '儿童成长陪伴师', 'https://traffic.libsyn.com/secure/learnchinese/6128.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/6128-qqbak1lh9mo49ptx08rkm24fxenvcl193j3o34jgwi.jpg', '', 'HSK6', 'https://mandarinbean.com/childrens-growth-companion/', '最近儿童成长陪伴师这一职业在社交媒体火了他们不用坐班打卡就能轻松月薪过万只需要陪孩子学习运动玩耍并在陪伴中观察孩子的习惯进而进行引导调整这一职业的从业者学历大多在本科及以上还有不少人是留学生很多是从幼师教培行业转行的在一些经济较发达的城市地区该职业普遍月薪在万元以上部分甚至能达到万元一个月选择一位有教育职业经历的陪伴师陪伴孩子成长逐渐成为一些职场父母的新选择儿童成长陪伴师的出现反映了现代社会中家庭对于教育和陪伴的重视家长们在多重身份的加持下职场与育儿的平衡常常成为家庭的困扰高质量陪伴正在成为职场父母的隐形刚需也正因此不少家庭会通过聘请陪伴师来弥补这份亲子之间的空缺一些家庭会根据需求选择高学历有留学经历的陪伴师以此为儿童创造双语教育环境也有人将重点放在性格开朗或是会做饭会开车等技能特质上希望孩子在得到陪伴的基础上也得到更好的照顾但是很多人也会混淆儿童成长陪伴师和家政保姆家庭教师的职责家务劳动学科教育等并不是他们的主要工作他们应该更像孩子的伙伴为孩子提供更多的情感支持在专业素质和个人品质方面也有较高的要求包括知识水平沟通技巧心理学知识责任感安全意识等等当然还需明确的是即便雇用了儿童陪伴师父母也不能完全卸下自己的责任父母的角色和影响是无可替代的他们不仅是孩子的养育者更是孩子的情感支柱和人生导师尽管外部资源和帮助可以提供支持但父母的参与对孩子来说依然是至关重要的', 'zuì jìn ér tóng chéng zhǎng péi bàn shī zhè yī zhí yè zài shè jiāo méi tǐ huǒ le tā men bù yòng zuò bān dǎ kǎ jiù néng qīng sōng yuè xīn guò wàn zhǐ xū yào péi hái zi xué xí yùn dòng wán shuǎ bìng zài péi bàn zhōng guān chá hái zi de xí guàn jìn ér jìn xíng yǐn dǎo tiáo zhěng zhè yī zhí yè de cóng yè zhě xué lì dà duō zài běn kē jí yǐ shàng hái yǒu bù shǎo rén shì liú xué shēng hěn duō shì cóng yòu shī jiào péi háng yè zhuǎn háng de zài yī xiē jīng jì jiào fā dá de chéng shì dì qū gāi zhí yè pǔ biàn yuè xīn zài wàn yuán yǐ shàng bù fèn shèn zhì néng dá dào wàn yuán yī gè yuè xuǎn zé yī wèi yǒu jiào yù zhí yè jīng lì de péi bàn shī péi bàn hái zi chéng zhǎng zhú jiàn chéng wéi yī xiē zhí chǎng fù mǔ de xīn xuǎn zé ér tóng chéng zhǎng péi bàn shī de chū xiàn fǎn yìng le xiàn dài shè huì zhōng jiā tíng duì yú jiào yù hé péi bàn de zhòng shì jiā zhǎng men zài duō chóng shēn fèn de jiā chí xià zhí chǎng yǔ yù ér de píng héng cháng cháng chéng wéi jiā tíng de kùn rǎo gāo zhì liàng péi bàn zhèng zài chéng wéi zhí chǎng fù mǔ de yǐn xíng gāng xū yě zhèng yīn cǐ bù shǎo jiā tíng huì tōng guò pìn qǐng péi bàn shī lái mí bǔ zhè fèn qīn zǐ zhī jiān de kòng quē yī xiē jiā tíng huì gēn jù xū qiú xuǎn zé gāo xué lì yǒu liú xué jīng lì de péi bàn shī yǐ cǐ wèi ér tóng chuàng zào shuāng yǔ jiào yù huán jìng yě yǒu rén jiāng zhòng diǎn fàng zài xìng gé kāi lǎng huò shì huì zuò fàn huì kāi chē děng jì néng tè zhì shàng xī wàng hái zi zài dé dào péi bàn de jī chǔ shàng yě dé dào gèng hǎo de zhào gù dàn shì hěn duō rén yě huì hùn xiáo ér tóng chéng zhǎng péi bàn shī hé jiā zhèng bǎo mǔ jiā tíng jiào shī de zhí zé jiā wù láo dòng xué kē jiào yù děng bìng bù shì tā men de zhǔ yào gōng zuò tā men yīng gāi gèng xiàng hái zi de huǒ bàn wèi hái zi tí gōng gèng duō de qíng gǎn zhī chí zài zhuān yè sù zhì hé gè rén pǐn zhì fāng miàn yě yǒu jiào gāo de yāo qiú bāo kuò zhī shí shuǐ píng gōu tōng jì qiǎo xīn lǐ xué zhī shí zé rèn gǎn ān quán yì shí děng děng dāng rán hái xū míng què de shì jí biàn gù yòng le ér tóng péi bàn shī fù mǔ yě bù néng wán quán xiè xià zì jǐ de zé rèn fù mǔ de jué sè hé yǐng xiǎng shì wú kě tì dài de tā men bù jǐn shì hái zi de yǎng yù zhě gèng shì hái zi de qíng gǎn zhī zhù hé rén shēng dǎo shī jǐn guǎn wài bù zī yuán hé bāng zhù kě yǐ tí gōng zhī chí dàn fù mǔ de cān yù duì hái zi lái shuō yī rán shì zhì guān zhòng yào de', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"zuì jìn:&lt;br /&gt;\r\nrecently (HSK3)\"><ruby><span class=\"si\">最近</span><span class=\"tr\">最近</span><rt>zuì jìn</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"ér tóng chéng zhǎng péi bàn shī:&lt;br /&gt;\r\nChildren\'s growth companion \"><ruby><span class=\"si\">儿童成长陪伴师</span><span class=\"tr\">兒童成長陪伴師</span><rt>ér tóng chéng zhǎng péi bàn shī</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"zhè:&lt;br /&gt;\r\nthis (HSK1