INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(160, 'jobs-most-likely-to-be-replaced-by-ai', 'Jobs most likely to be replaced by AI', '最可能被AI取代的工作', 'https://traffic.libsyn.com/secure/learnchinese/6126.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/6126-qnpdn0iyz2phikspm47ckx1ttmozumqrryrwx9nvmm.png', '', 'HSK6', 'https://mandarinbean.com/jobs-most-likely-to-be-replaced-by-ai/', '随着的发展和更新生成式的大潮席卷全球而专家预计这股浪潮也将影响全球三亿个全职工作各大公司也开始纷纷引入替代人类员工并且表现相当出色哪些工作最容易受到的影响呢科技领域中程序员数据分析师软件工程师等相对更容易受到的影响因为现在处理数据写程序的速度比人类更快过去需要一整个团队完成的工作现在只需要几个人协作就能完成的特长之一是处理数据金融领域的会计师财务分析师财务顾问等因为需要处理大量的数据也比较容易受到影响目前已经有很多模型开始整合数据预测股票市场评估投资组合的表现并进行商业投资了那些侧重于文字语言相关的工作更岌岌可危比如法律领域的律师助理因为这个岗位要求结合法律知识消化大量的新资讯然后整理所有的内容帮助人们理解而很擅长这样的工作媒体领域则是内容创作者新闻工作者广告从业者等则可能会被影响目前不少新闻媒体也开始尝试使用生成内容而在制作报告写文章等方面都有不错的表现除了以上这些岗位老师平面设计师客服人员等都被列为可能被替代的工作但是专家们也指出尽管的发展让人惊叹目前大部分的工作难以完全自动化依然需要人类的协助才能完成', 'suí zhe de fā zhǎn hé gēng xīn shēng chéng shì de dà cháo xí juǎn quán qiú ér zhuān jiā yù jì zhè gǔ làng cháo yě jiāng yǐng xiǎng quán qiú sān yì gè quán zhí gōng zuò gè dà gōng sī yě kāi shǐ fēn fēn yǐn rù tì dài rén lèi yuán gōng bìng qiě biǎo xiàn xiāng dāng chū sè nǎ xiē gōng zuò zuì róng yì shòu dào de yǐng xiǎng ne kē jì lǐng yù zhōng chéng xù yuán shù jù fēn xī shī ruǎn jiàn gōng chéng shī děng xiāng duì gèng róng yì shòu dào de yǐng xiǎng yīn wèi xiàn zài chǔ lǐ shù jù xiě chéng xù de sù dù bǐ rén lèi gèng kuài guò qù xū yào yī zhěng gè tuán duì wán chéng de gōng zuò xiàn zài zhǐ xū yào jǐ gè rén xié zuò jiù néng wán chéng de tè cháng zhī yī shì chǔ lǐ shù jù jīn róng lǐng yù de kuài jì shī cái wù fēn xī shī cái wù gù wèn děng yīn wèi xū yào chǔ lǐ dà liàng de shù jù yě bǐ jiào róng yì shòu dào yǐng xiǎng mù qián yǐ jīng yǒu hěn duō mó xíng kāi shǐ zhěng hé shù jù yù cè gǔ piào shì chǎng píng gū tóu zī zǔ hé de biǎo xiàn bìng jìn xíng shāng yè tóu zī le nà xiē cè zhòng yú wén zì yǔ yán xiāng guān de gōng zuò gèng jí jí kě wēi bǐ rú fǎ lǜ lǐng yù de lǜ shī zhù lǐ yīn wèi zhè gè gǎng wèi yāo qiú jié hé fǎ lǜ zhī shí xiāo huà dà liàng de xīn zī xùn rán hòu zhěng lǐ suǒ yǒu de nèi róng bāng zhù rén men lǐ jiě ér hěn shàn cháng zhè yàng de gōng zuò méi tǐ lǐng yù zé shì nèi róng chuàng zuò zhě xīn wén gōng zuò zhě guǎng gào cóng yè zhě děng zé kě néng huì bèi yǐng xiǎng mù qián bù shǎo xīn wén méi tǐ yě kāi shǐ cháng shì shǐ yòng shēng chéng nèi róng ér zài zhì zuò bào gào xiě wén zhāng děng fāng miàn dōu yǒu bù cuò de biǎo xiàn chú le yǐ shàng zhè xiē gǎng wèi lǎo shī píng miàn shè jì shī kè fú rén yuán děng dōu bèi liè wéi kě néng bèi tì dài de gōng zuò dàn shì zhuān jiā men yě zhǐ chū jǐn guǎn de fā zhǎn ràng rén jīng tàn mù qián dà bù fèn de gōng zuò nán yǐ wán quán zì dòng huà yī rán xū yào rén lèi de xié zhù cái néng wán chéng', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"suí zhe:&lt;br /&gt;\r\nalong with (HSK4)\"><ruby><span class=\"si\">随着</span><span class=\"tr\">隨著</span><rt>suí zhe</rt></ruby></abbr>ChatGPT<abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"fā zhǎn:&lt;br /&gt;\r\ndevelop (HSK4)\"><ruby><span class=\"si\">发展</span><span class=\"tr\">發展</span><rt>fā zhǎn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"hé:&lt;br /&gt;\r\nand, with (HSK1)\"><ruby><span class=\"si\">和</span><span class=\"tr\">和</span><rt>hé</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gēng xīn:&lt;br /&gt;\r\nrenew (HSK6)\"><ruby><span class=\"si\">更新</span><span class=\"tr\">更新</span><rt>gēng xīn</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"shēng chéng:&lt;br /&gt;\r\ngenerate\"><ruby><span class=\"si\">生成</span><span class=\"tr\">生成</span><rt>shēng chéng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"shì:&lt;br /&gt;\r\nMode\"><ruby><span 