INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(161, 'harbin-tourism-explodes', 'Harbin tourism explodes', '哈尔滨旅游业爆火', 'https://traffic.libsyn.com/secure/learnchinese/6125.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/6125-qkexvzjo95l566vzrjomrcq6vu59874ii4a0f49q36.jpg', '', 'HSK6', 'https://mandarinbean.com/harbin-tourism-explodes/', '这个冬天中国东北的冰雪旅游业迎来了显著的繁荣特别是零下度的冰城哈尔滨成了南方游客心心念念的地方社交平台上围绕哈尔滨的话题每天都在产生从东北洗浴中心到南方小土豆从人造月亮到饭店的冻梨从丹顶鹤到东北少数民族游客纷纷慕名而来感受这座城市的幽默与热情这一热潮不仅吸引了大量游客而且对股市产生了积极影响特别是在冰雪旅游板块很多公司的股价急剧上升哈尔滨旅游业在新年假期创下了历史新高接待游客超过万人次总收入近亿元根据同程旅游的数据哈尔滨在目的地热度上排名全国第四这种冬季旅游的趋势预计将持续增长', 'zhè gè dōng tiān Zhōngguó dōng běi de bīng xuě lǚ yóu yè yíng lái le xiǎn zhù de fán róng tè bié shì líng xià dù de bīng chéng Hāěrbīn chéng le nán fāng yóu kè xīn xīn niàn niàn de dì fāng shè jiāo píng tái shàng wéi rào Hāěrbīn de huà tí měi tiān dōu zài chǎn shēng cóng dōng běi xǐ yù zhōng xīn dào nán fāng xiǎo tǔ dòu cóng rén zào yuè liàng dào fàn diàn de dòng lí cóng dān dǐng hè dào dōng běi shǎo shù mín zú yóu kè fēn fēn mù míng ér lái gǎn shòu zhè zuò chéng shì de yōu mò yǔ rè qíng zhè yī rè cháo bù jǐn xī yǐn le dà liàng yóu kè ér qiě duì gǔ shì chǎn shēng le jī jí yǐng xiǎng tè bié shì zài bīng xuě lǚ yóu bǎn kuài hěn duō gōng sī de gǔ jià jí jù shàng shēng Hāěrbīn lǚ yóu yè zài xīn nián jià qī chuàng xià le lì shǐ xīn gāo jiē dài yóu kè chāo guò wàn rén cì zǒng shōu rù jìn yì yuán gēn jù Tóngchéng lǚ yóu de shù jù Hāěrbīn zài mù dì dì rè dù shàng pái míng quán guó dì sì zhè zhǒng dōng jì lǚ yóu de qū shì yù jì jiāng chí xù zēng zhǎng', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"zhè:&lt;br /&gt;\r\nthis (HSK1)\"><ruby><span class=\"si\">这</span><span class=\"tr\">這</span><rt>zhè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"gè:&lt;br /&gt;\r\n(measure word) (HSK1)\"><ruby><span class=\"si\">个</span><span class=\"tr\">個</span><rt>gè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dōng tiān:&lt;br /&gt;\r\nwinter\"><ruby><span class=\"si\">冬天</span><span class=\"tr\">冬天</span><rt>dōng tiān</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"Zhōngguó:&lt;br /&gt;\r\nChina (HSK1)\"><ruby><span class=\"si\">中国</span><span class=\"tr\">中國</span><rt>Zhōngguó</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"dōng běi:&lt;br /&gt;\r\nnortheast\"><ruby><span class=\"si\">东北</span><span class=\"tr\">東北</span><rt>dōng běi</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"bīng xuě:&lt;br /&gt;\r\nice and snow\"><ruby><span class=\"si\">冰雪</span><span class=\"tr\">冰雪</span><rt>bīng xuě</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"lǚ yóu:&lt;br /&gt;\r\ntravel (HSK2)\"><ruby><span class=\"si\">旅游</span><span class=\"tr\">旅游</span><rt>lǚ yóu</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yè:&lt;br /&gt;\r\nindustry\"><ruby><span class=\"si\">业</span><span class=\"tr\">業</span><rt>yè</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yíng lái:&lt;br /&gt;\r\nwelcome\"><ruby><span class=\"si\">迎来</span><span class=\"tr\">迎來</span><rt>yíng lái</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"le:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">了</span><span class=\"tr\">了</span><rt>le</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiǎn zhù:&lt;br /&gt;\r\nsignificantly (HSK6)\"><ruby><span class=\"si\">显著</span><span class=\"tr\">顯著</span><rt>xiǎn zhù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"de:&lt;br /&gt;\r\n(aux. word) (HSK1)\"><ruby><span class=\"si\">的</span><span class=\"tr\">的</span><rt>de</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"fán róng:&lt;br /&gt;\r\nprosperity (HSK5)\"><ruby><span class=\"si\">繁荣</span><span class=\"tr\">繁榮</span><rt>fán róng</rt></ruby></ab