INSERT INTO `stories` (`id`, `slug`, `title_english`, `title_chinese`, `audio_url`, `image_url`, `tags`, `hsk_level`, `story_url`, `chinese_text`, `pinyin_text`, `content_html`, `created_at`) VALUES
(162, 'the-latest-china-visa-policy', 'The latest China visa policy', '最新的中国签证政策', 'https://traffic.libsyn.com/secure/learnchinese/6124.mp3', 'https://mandarinbean.com/wp-content/uploads/elementor/thumbs/6124-qil5sf6w4qmd2fjl136u4aepfg9dwsbiu1op9fm6aa.jpg', '', 'HSK6', 'https://mandarinbean.com/the-latest-china-visa-policy/', '中国国家移民管理局近日宣布五项新措施进一步便利外籍人员来中国急需来中国从事商贸合作投资创业探亲等处理非外交公务活动的外籍人员如果来不及在境外办理签证可以凭相关的邀请函等证明材料向口岸签证机关申请办理口岸签证后入境并可凭此办理换发多次出入境有效签证此外所有外籍人员来中国若在北京上海广州深圳杭州厦门成都西安等城市的九个机场过境小时内可免签无需查验手续除此之外有简化签证延期换发补发流程为多次出入境的外籍人员提供再入境签证服务简化签证申办材料等措施这些改革有助于中国对外开放促进高质量发展满足中外企业及人员的新需求', 'Zhōngguó guó jiā yí mín guǎn lǐ jú jìn rì xuān bù wǔ xiàng xīn cuò shī jìn yī bù biàn lì wài jí rén yuán lái Zhōngguó jí xū lái Zhōngguó cóng shì shāng mào hé zuò tóu zī chuàng yè tàn qīn děng chǔ lǐ fēi wài jiāo gōng wù huó dòng de wài jí rén yuán rú guǒ lái bù jí zài jìng wài bàn lǐ qiān zhèng kě yǐ píng xiāng guān de yāo qǐng hán děng zhèng míng cái liào xiàng kǒu àn qiān zhèng jī guān shēn qǐng bàn lǐ kǒu àn qiān zhèng hòu rù jìng bìng kě píng cǐ bàn lǐ huàn fā duō cì chū rù jìng yǒu xiào qiān zhèng cǐ wài suǒ yǒu wài jí rén yuán lái Zhōngguó ruò zài Běijīng Shànghǎi Guǎngzhōu Shēnzhèn Hángzhōu Xiàmén Chéngdū xī’ān děng chéng shì de jiǔ gè jī chǎng guò jìng xiǎo shí nèi kě miǎn qiān wú xū chá yàn shǒu xù chú cǐ zhī wài yǒu jiǎn huà qiān zhèng yán qī huàn fā bǔ fā liú chéng wèi duō cì chū rù jìng de wài jí rén yuán tí gōng zài rù jìng qiān zhèng fú wù jiǎn huà qiān zhèng shēn bàn cái liào děng cuò shī zhè xiē gǎi gé yǒu zhù yú Zhōngguó duì wài kāi fàng cù jìn gāo zhì liàng fā zhǎn mǎn zú zhōng wài qǐ yè jí rén yuán de xīn xū qiú', '<div class=\"elementor-element elementor-element-4064e155 elementor-widget elementor-widget-theme-post-content\" data-element_type=\"widget\" data-id=\"4064e155\" data-widget_type=\"theme-post-content.default\">\r\n<div class=\"elementor-widget-container\">\r\n<p><abbr rel=\"tooltip\" title=\"Zhōngguó:&lt;br /&gt;\r\nChina (HSK1)\"><ruby><span class=\"si\">中国</span><span class=\"tr\">中國</span><rt>Zhōngguó</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"guó jiā:&lt;br /&gt;\r\nnation (HSK3)\"><ruby><span class=\"si\">国家</span><span class=\"tr\">國家</span><rt>guó jiā</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yí mín:&lt;br /&gt;\r\nmigrant (HSK5)\"><ruby><span class=\"si\">移民</span><span class=\"tr\">移民</span><rt>yí mín</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"guǎn lǐ:&lt;br /&gt;\r\nmanage (HSK4)\"><ruby><span class=\"si\">管理</span><span class=\"tr\">管理</span><rt>guǎn lǐ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jú:&lt;br /&gt;\r\nbureau\"><ruby><span class=\"si\">局</span><span class=\"tr\">局</span><rt>jú</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"jìn:&lt;br /&gt;\r\nrecent (HSK2)\"><ruby><span class=\"si\">近</span><span class=\"tr\">近</span><rt>jìn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"rì:&lt;br /&gt;\r\nday (HSK1)\"><ruby><span class=\"si\">日</span><span class=\"tr\">日</span><rt>rì</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xuān bù:&lt;br /&gt;\r\nannounce (HSK5)\"><ruby><span class=\"si\">宣布</span><span class=\"tr\">宣布</span><rt>xuān bù</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"wǔ:&lt;br /&gt;\r\nfive (HSK1)\"><ruby><span class=\"si\">五</span><span class=\"tr\">五</span><rt>wǔ</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xiàng:&lt;br /&gt;\r\n(measure word) (HSK5)\"><ruby><span class=\"si\">项</span><span class=\"tr\">項</span><rt>xiàng</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"xīn:&lt;br /&gt;\r\nnew (HSK2)\"><ruby><span class=\"si\">新</span><span class=\"tr\">新</span><rt>xīn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"cuò shī:&lt;br /&gt;\r\nmeasure (HSK5)\"><ruby><span class=\"si\">措施</span><span class=\"tr\">措施</span><rt>cuò shī</rt></ruby></abbr>，<abbr rel=\"tooltip\" title=\"jìn:&lt;br /&gt;\r\nfurther (HSK2)\"><ruby><span class=\"si\">进</span><span class=\"tr\">進</span><rt>jìn</rt></ruby></abbr><abbr rel=\"tooltip\" title=\"yī:&lt;br /&gt;\r\none (HSK1)\"><ru